export default LoadingSpinner;

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, MessageCircle, Sparkles } from 'lucide-react';
import { askIslamicScholar } from '../services/geminiService';
import { ChatMessage } from '../types';

interface AIChatProps {
  context?: string; // Current Surah context
}

const AIChat: React.FC<AIChatProps> = ({ context }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: 'السلام علیکم! میں آپ کا قرآن اسسٹنٹ ہوں۔ آپ کسی بھی آیت یا سورت کے بارے میں سوال پوچھ سکتے ہیں۔ (Assalam-o-Alaikum! I am your Quran Assistant. You can ask about any Ayah or Surah.)',
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const toggleChat = () => setIsOpen(!isOpen);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await askIslamicScholar(userMessage.text, context);
      const aiMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
      };
      setMessages((prev) => [...prev, aiMessage]);
    } catch (error) {
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: 'معذرت، کچھ غلط ہو گیا۔ براہ کرم دوبارہ کوشش کریں۔',
        isError: true,
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      {/* Floating Action Button */}
      <button
        onClick={toggleChat}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-lg transition-all duration-300 ${
          isOpen ? 'bg-red-500 hover:bg-red-600' : 'bg-emerald-600 hover:bg-emerald-700'
        } text-white flex items-center justify-center`}
        aria-label="Toggle AI Chat"
      >
        {isOpen ? <X size={24} /> : <MessageCircle size={28} />}
      </button>

      {/* Chat Window */}
      <div
        className={`fixed bottom-24 right-6 w-80 md:w-96 bg-white rounded-2xl shadow-2xl border border-gray-100 z-50 transform transition-all duration-300 origin-bottom-right flex flex-col ${
          isOpen ? 'scale-100 opacity-100' : 'scale-0 opacity-0 pointer-events-none'
        }`}
        style={{ maxHeight: 'calc(100vh - 120px)', height: '500px' }}
      >
        {/* Header */}
        <div className="bg-emerald-600 p-4 rounded-t-2xl flex items-center justify-between">
          <div className="flex items-center space-x-2 space-x-reverse text-white">
            <Sparkles size={20} className="text-gold-400" />
            <h3 className="font-bold text-lg">قرآن اسسٹنٹ (AI)</h3>
          </div>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-paper bg-opacity-50">
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap ${
                  msg.role === 'user'
                    ? 'bg-emerald-600 text-white rounded-br-none'
                    : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'
                } ${msg.isError ? 'bg-red-50 border-red-200 text-red-600' : ''}`}
                dir="auto"
              >
                {msg.text}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white border border-gray-200 p-3 rounded-2xl rounded-bl-none shadow-sm flex items-center space-x-2 space-x-reverse">
                <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce delay-100" />
                <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce delay-200" />
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 border-t border-gray-100 bg-white rounded-b-2xl">
          <div className="flex items-center space-x-2 space-x-reverse">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="سوال پوچھیں..."
              className="flex-1 border border-gray-300 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right font-urdu placeholder:font-sans"
              dir="rtl"
            />
            <button
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="bg-emerald-600 text-white p-2 rounded-full hover:bg-emerald-700 disabled:opacity-50 transition-colors"
            >
              <Send size={20} className={isLoading ? 'opacity-0' : ''} />
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default AIChat;

import React, { useEffect, useState, useRef } from 'react';
import { ArrowLeft, BookOpen, Share2 } from 'lucide-react';
import { CombinedSurahData } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  onBack: () => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, onBack }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const headerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let isMounted = true;

    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      try {
        const result = await getSurahDetails(surahNumber);
        if (isMounted) {
          setData(result);
        }
      } catch (err) {
        if (isMounted) {
          setError('Failed to load Surah. Please check your internet connection.');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber]);

  useEffect(() => {
    // Scroll to top when loaded
    window.scrollTo(0, 0);
  }, [data]);

  if (loading) return <LoadingSpinner />;
  if (error || !data) return (
    <div className="flex flex-col items-center justify-center min-h-[50vh] text-center px-4">
      <div className="text-red-500 text-xl mb-4">Error loading content</div>
      <p className="text-gray-600 mb-6">{error}</p>
      <button 
        onClick={onBack}
        className="flex items-center px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
      >
        <ArrowLeft size={18} className="mr-2" />
        Go Back
      </button>
    </div>
  );

  const { surahInfo, arabicAyahs, urduAyahs } = data;

  return (
    <div className="min-h-screen bg-paper pb-20 relative">
       {/* Sticky Header */}
      <div 
        ref={headerRef}
        className="sticky top-0 z-30 bg-paper/95 backdrop-blur-sm border-b border-emerald-100 shadow-sm transition-all duration-300"
      >
        <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
            <button 
                onClick={onBack}
                className="p-2 text-emerald-800 hover:bg-emerald-100 rounded-full transition-colors"
                aria-label="Back to List"
            >
                <ArrowLeft size={24} />
            </button>
            <div className="text-center">
                <h1 className="text-2xl font-arabic font-bold text-emerald-900">{surahInfo.name}</h1>
                <p className="text-xs text-emerald-600 font-medium tracking-wide uppercase">{surahInfo.englishName} • {surahInfo.numberOfAyahs} Ayahs</p>
            </div>
             <button 
                className="p-2 text-emerald-800 hover:bg-emerald-100 rounded-full transition-colors opacity-0 md:opacity-100"
            >
                <Share2 size={24} />
            </button>
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 py-8">

        {/* Bismillah */}
        <div className="flex justify-center mb-12 mt-4">
            <div className="relative p-8">
                <img 
                    src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" 
                    alt="Bismillah" 
                    className="w-64 md:w-80 h-auto opacity-90 mx-auto"
                />
            </div>
        </div>

        {/* Verses */}
        <div className="space-y-8">
            {arabicAyahs.map((ayah, index) => {
                const urduAyah = urduAyahs[index];

                // Skip Bismillah in text if it is the first ayah of a surah (except Fatiha)
                // The API usually handles this, but sometimes raw text includes it.
                // For simplified rendering, we just render what API gives.

                return (
                    <div 
                        key={ayah.number} 
                        className="group relative bg-white border border-emerald-50 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow duration-300"
                    >
                         {/* Ayah Number Badge */}
                        <div className="absolute -top-3 -left-3 md:-left-4 bg-emerald-100 text-emerald-800 w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center text-xs md:text-sm font-bold border-2 border-white shadow-sm">
                            {ayah.numberInSurah}
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-6" dir="rtl">
                            <p className="font-arabic text-3xl md:text-4xl leading-[2.2] text-gray-900">
                                {ayah.text} 
                                <span className="text-gold-500 text-2xl mx-2 font-arabic">۝</span>
                            </p>
                        </div>

                        {/* Divider */}
                        <div className="h-px bg-gradient-to-r from-transparent via-emerald-100 to-transparent my-4"></div>

                        {/* Urdu Text */}
                        <div className="text-right" dir="rtl">
                            <p className="font-urdu text-xl md:text-2xl leading-relaxed text-gray-700">
                                {urduAyah ? urduAyah.text : 'Translation loading...'}
                            </p>
                        </div>

                        {/* Action Bar (Optional, for sharing or playing audio later) */}
                        <div className="mt-4 flex justify-end opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                            <button 
                                className="text-xs text-emerald-600 flex items-center hover:underline"
                                onClick={() => {
                                    // Could implement copy text here
                                }}
                            >
                                <BookOpen size={14} className="mr-1" /> Copy Verse
                            </button>
                        </div>
                    </div>
                );
            })}
        </div>

        {/* Footer Navigation within Reader */}
        <div className="mt-12 flex justify-between">
           {/* Can add Next/Prev Surah buttons here */}
        </div>

      </div>

      {/* AI Assistant Contextually Aware of this Surah */}
      <AIChat context={`User is currently reading Surah ${surahInfo.englishName} (${surahInfo.name}), which has ${surahInfo.numberOfAyahs} verses. Revelation type: ${surahInfo.revelationType}.`} />
    </div>
  );
};

export default Reader;

import React, { useState, useEffect } from 'react';
import { Search, Book } from 'lucide-react';
import { Surah } from '../types';
import { getSurahList } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface SurahListProps {
  onSelectSurah: (surahNumber: number) => void;
}

const SurahList: React.FC<SurahListProps> = ({ onSelectSurah }) => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [filteredSurahs, setFilteredSurahs] = useState<Surah[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const list = await getSurahList();
        setSurahs(list);
        setFilteredSurahs(list);
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const lowerSearch = search.toLowerCase();
    const filtered = surahs.filter(
      (s) =>
        s.englishName.toLowerCase().includes(lowerSearch) ||
        s.englishNameTranslation.toLowerCase().includes(lowerSearch) ||
        s.number.toString().includes(lowerSearch)
    );
    setFilteredSurahs(filtered);
  }, [search, surahs]);

  return (
    <div className="min-h-screen bg-paper">
      {/* Hero Section */}
      <div className="bg-emerald-900 text-white pt-12 pb-24 px-6 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-800 rounded-full mix-blend-multiply filter blur-3xl opacity-50 -translate-y-1/2 translate-x-1/2"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-emerald-800 rounded-full mix-blend-multiply filter blur-3xl opacity-50 translate-y-1/2 -translate-x-1/2"></div>

        <div className="max-w-4xl mx-auto text-center relative z-10">
          <h1 className="font-arabic text-5xl md:text-6xl mb-2 text-gold-400">القرآن الكريم</h1>
          <p className="text-emerald-100 text-lg md:text-xl font-light tracking-wider mb-8">The Holy Quran</p>

          <div className="relative max-w-lg mx-auto">
            <input
              type="text"
              placeholder="Search Surah (e.g. Yaseen, 36)..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full py-4 px-6 pl-12 rounded-full bg-emerald-950/50 backdrop-blur-md border border-emerald-700/50 text-white placeholder-emerald-400 focus:outline-none focus:ring-2 focus:ring-gold-500 shadow-xl transition-all"
            />
            <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-emerald-400" size={20} />
          </div>
        </div>
      </div>

      {/* Surah Grid */}
      <div className="max-w-6xl mx-auto px-4 -mt-12 relative z-20 pb-20">
        {loading ? (
          <div className="bg-white rounded-2xl shadow-lg p-8">
            <LoadingSpinner />
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredSurahs.map((surah) => (
              <div
                key={surah.number}
                onClick={() => onSelectSurah(surah.number)}
                className="bg-white hover:bg-emerald-50 border border-emerald-50 hover:border-emerald-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-all duration-300 cursor-pointer group flex items-center justify-between"
              >
                <div className="flex items-center space-x-4">
                  <div className="w-12 h-12 relative flex items-center justify-center">
                     {/* Decorative Number Container */}
                     <div className="absolute inset-0 bg-emerald-100 rounded-lg transform rotate-45 group-hover:rotate-90 transition-transform duration-300"></div>
                     <span className="relative font-bold text-emerald-800">{surah.number}</span>
                  </div>
                  <div className="text-left">
                    <h3 className="font-semibold text-gray-800 group-hover:text-emerald-900">{surah.englishName}</h3>
                    <p className="text-xs text-gray-500 uppercase tracking-wide">{surah.englishNameTranslation}</p>
                  </div>
                </div>
                <div className="text-right">
                    <h3 className="font-arabic text-xl text-emerald-800 mb-1">{surah.name}</h3>
                    <p className="text-xs text-gray-400">{surah.numberOfAyahs} Verses</p>
                </div>
              </div>
            ))}
            {filteredSurahs.length === 0 && (
                <div className="col-span-full text-center py-12 text-gray-500">
                    No Surahs found matching "{search}"
                </div>
            )}
          </div>
        )}
      </div>

      <AIChat context="User is browsing the list of Surahs in the Holy Quran." />
    </div>
  );
};

export default SurahList;

import React, { useState, useEffect } from 'react';
import SurahList from './components/SurahList';
import Reader from './components/Reader';

// A simple Hash Router implementation for single-file robustness
const App: React.FC = () => {
  const [view, setView] = useState<'list' | 'reader'>('list');
  const [currentSurah, setCurrentSurah] = useState<number>(1);

  useEffect(() => {
    // Check hash on load
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash.startsWith('#surah/')) {
        const surahNum = parseInt(hash.split('/')[1], 10);
        if (!isNaN(surahNum)) {
          setCurrentSurah(surahNum);
          setView('reader');
        } else {
            setView('list');
        }
      } else {
        setView('list');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange(); // Initial check

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const handleSelectSurah = (surahNumber: number) => {
    window.location.hash = `surah/${surahNumber}`;
  };

  const handleBack = () => {
    window.location.hash = ''; // Clears hash, triggers 'list' view via useEffect
  };

  return (
    <div className="antialiased text-gray-900 bg-paper min-h-screen font-sans selection:bg-emerald-200 selection:text-emerald-900">
      {view === 'list' && <SurahList onSelectSurah={handleSelectSurah} />}
      {view === 'reader' && <Reader surahNumber={currentSurah} onBack={handleBack} />}
    </div>
  );
};

export default App;

