import { Surah, CombinedSurahData, SurahDetail } from '../types';

const BASE_URL = 'https://api.alquran.cloud/v1';

export const getSurahList = async (): Promise<Surah[]> => {
  try {
    const response = await fetch(`${BASE_URL}/surah`);
    const data = await response.json();
    return data.data;
  } catch (error) {
    console.error('Error fetching surah list:', error);
    throw error;
  }
};

export const getSurahDetails = async (surahNumber: number): Promise<CombinedSurahData> => {
  try {
    // Fetch Arabic (Uthmani), Urdu (Jalandhry), and Audio (Mishary Rashid Alafasy)
    // We explicitly request quran-uthmani to ensure Usmani punctuation/script
    const response = await fetch(
      `${BASE_URL}/surah/${surahNumber}/editions/quran-uthmani,ur.jalandhry,ar.alafasy`
    );
    const data = await response.json();

    // The API returns an array, but order isn't always guaranteed. 
    // We must find the specific editions by their properties.
    const allEditions: SurahDetail[] = data.data;

    const arabicData = allEditions.find(e => e.edition?.identifier === 'quran-uthmani') || allEditions[0];
    const urduData = allEditions.find(e => e.edition?.identifier === 'ur.jalandhry') || allEditions[1];
    const audioData = allEditions.find(e => e.edition?.identifier === 'ar.alafasy') || allEditions[2];

    // Merge audio URL into arabic ayahs
    const mergedArabicAyahs = arabicData.ayahs.map((ayah, index) => ({
      ...ayah,
      audio: audioData.ayahs[index]?.audio
    }));

    return {
      surahInfo: {
        number: arabicData.number,
        name: arabicData.name,
        englishName: arabicData.englishName,
        englishNameTranslation: arabicData.englishNameTranslation,
        numberOfAyahs: arabicData.numberOfAyahs,
        revelationType: arabicData.revelationType,
      },
      arabicAyahs: mergedArabicAyahs,
      urduAyahs: urduData.ayahs,
    };
  } catch (error) {
    console.error(`Error fetching surah ${surahNumber}:`, error);
    throw error;
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { ArrowLeft, BookOpen, Share2, Play, Pause, SkipForward, SkipBack, Volume2, Download, CheckCircle, Loader2 } from 'lucide-react';
import { CombinedSurahData } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  onBack: () => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, onBack }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);

  // Offline/Download States
  const [downloading, setDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState(0);
  const [isOfflineReady, setIsOfflineReady] = useState(false);

  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    let isMounted = true;

    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsOfflineReady(false);

      try {
        const result = await getSurahDetails(surahNumber);
        if (isMounted) {
          setData(result);
          checkOfflineAvailability(result);
        }
      } catch (err) {
        if (isMounted) {
          setError('Failed to load Surah. Please check your internet connection.');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber]);

  useEffect(() => {
    if (data && currentAyahIndex === -1) {
        window.scrollTo(0, 0);
    }
  }, [data]);

  // Check if audio is already cached
  const checkOfflineAvailability = async (surahData: CombinedSurahData) => {
    if (!('caches' in window)) return;

    try {
        const cache = await caches.open('quran-audio-v1');
        const audioUrls = surahData.arabicAyahs.map(a => a.audio).filter(Boolean) as string[];

        // Check a random sample to guess availability (checking all is expensive on init)
        // Or checking all if list is small. Let's check all but efficiently.
        let cachedCount = 0;
        const checks = audioUrls.map(url => cache.match(url).then(res => res ? 1 : 0));
        const results = await Promise.all(checks);
        const totalCached = results.reduce((a: number, b: number) => a + b, 0);

        if (totalCached === audioUrls.length && audioUrls.length > 0) {
            setIsOfflineReady(true);
        }
    } catch (e) {
        console.error("Cache check failed", e);
    }
  };

  const handleDownloadSurah = async () => {
    if (!data || downloading) return;
    setDownloading(true);
    setDownloadProgress(0);

    const audioUrls = data.arabicAyahs.map(a => a.audio).filter(Boolean) as string[];
    const total = audioUrls.length;
    let completed = 0;

    try {
        // Use a concurrency limit to avoid browser blocking
        const limit = 5;
        const queue = [...audioUrls];

        const worker = async () => {
             while(queue.length > 0) {
                 const url = queue.shift();
                 if(!url) break;
                 try {
                     await fetch(url); // Trigger Service Worker Cache
                     completed++;
                     setDownloadProgress(Math.round((completed / total) * 100));
                 } catch (e) {
                     console.error("Failed to fetch", url);
                 }
             }
        };

        const workers = Array(Math.min(limit, total)).fill(null).map(() => worker());
        await Promise.all(workers);

        setIsOfflineReady(true);
    } catch (e) {
        console.error("Download failed", e);
    } finally {
        setDownloading(false);
    }
  };

  // Handle Audio Playback
  useEffect(() => {
    if (currentAyahIndex !== -1 && audioRef.current && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];
      if (ayah?.audio) {
        audioRef.current.src = ayah.audio;
        audioRef.current.play().catch(e => {
            console.error("Playback failed", e);
            setIsPlaying(false);
        });
        setIsPlaying(true);

        const element = document.getElementById(`ayah-${ayah.number}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            const elementPosition = element.getBoundingClientRect().top + window.scrollY;
            const offsetPosition = elementPosition - headerHeight - 20;

            window.scrollTo({
                top: offsetPosition,
                behavior: 'smooth'
            });
        }
      }
    } else if (currentAyahIndex === -1 && audioRef.current) {
        audioRef.current.pause();
        setIsPlaying(false);
    }
  }, [currentAyahIndex, data]);

  const togglePlaySurah = () => {
    if (isPlaying) {
        audioRef.current?.pause();
        setIsPlaying(false);
    } else {
        if (currentAyahIndex === -1) {
            setCurrentAyahIndex(0);
        } else {
            audioRef.current?.play();
            setIsPlaying(true);
        }
    }
  };

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const playSpecificAyah = (index: number) => {
    if (currentAyahIndex === index && isPlaying) {
        audioRef.current?.pause();
        setIsPlaying(false);
    } else {
        setCurrentAyahIndex(index);
        setIsPlaying(true);
    }
  };

  if (loading) return <LoadingSpinner />;
  if (error || !data) return (
    <div className="flex flex-col items-center justify-center min-h-[50vh] text-center px-4">
      <div className="text-red-500 text-xl mb-4">Error loading content</div>
      <p className="text-gray-600 mb-6">{error}</p>
      <button 
        onClick={onBack}
        className="flex items-center px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
      >
        <ArrowLeft size={18} className="mr-2" />
        Go Back
      </button>
    </div>
  );

  const { surahInfo, arabicAyahs, urduAyahs } = data;

  return (
    <div className="min-h-screen bg-paper pb-20 relative">
      <audio 
        ref={audioRef} 
        onEnded={handleAyahEnd}
        onError={() => {
            console.error("Audio error");
            setIsPlaying(false);
        }}
      />

       {/* Sticky Header */}
      <div 
        ref={headerRef}
        className="sticky top-0 z-30 bg-paper/95 backdrop-blur-sm border-b border-emerald-100 shadow-sm transition-all duration-300"
      >
        <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button 
                    onClick={onBack}
                    className="p-2 text-emerald-800 hover:bg-emerald-100 rounded-full transition-colors mr-2"
                    aria-label="Back to List"
                >
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                    <h1 className="text-xl font-arabic font-bold text-emerald-900">{surahInfo.name}</h1>
                </div>
            </div>

            {/* Player Controls in Header */}
            <div className="flex items-center space-x-1 md:space-x-4">

                 {/* Download Button */}
                 <button 
                    onClick={handleDownloadSurah}
                    disabled={isOfflineReady || downloading}
                    className={`flex items-center justify-center px-3 py-1.5 rounded-full text-xs md:text-sm font-medium transition-all ${
                        isOfflineReady 
                        ? 'bg-emerald-100 text-emerald-700 cursor-default'
                        : downloading 
                            ? 'bg-gold-100 text-gold-700 cursor-wait'
                            : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'
                    }`}
                 >
                    {isOfflineReady ? (
                        <>
                            <CheckCircle size={16} className="mr-1.5" />
                            <span className="hidden md:inline">Offline Ready</span>
                        </>
                    ) : downloading ? (
                        <>
                            <Loader2 size={16} className="mr-1.5 animate-spin" />
                            <span>{downloadProgress}%</span>
                        </>
                    ) : (
                        <>
                            <Download size={16} className="mr-1.5" />
                            <span className="hidden md:inline">Download</span>
                        </>
                    )}
                 </button>

                 <div className="h-6 w-px bg-emerald-200 mx-2 hidden md:block"></div>

                 <div className="flex items-center space-x-2 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
                    <button 
                        onClick={() => {
                            if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1);
                        }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1 md:p-2 text-emerald-700 hover:text-emerald-900 disabled:opacity-30 transition-colors"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>

                    <button 
                        onClick={togglePlaySurah}
                        className={`w-8 h-8 md:w-10 md:h-10 flex items-center justify-center rounded-full text-white shadow-md transition-all ${
                            isPlaying ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-emerald-500 hover:bg-emerald-600'
                        }`}
                    >
                        {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
                    </button>

                    <button 
                        onClick={() => {
                            if(currentAyahIndex < arabicAyahs.length - 1) setCurrentAyahIndex(prev => prev + 1);
