    return () => { isMounted = false; };
  }, [surahNumber]);

  useEffect(() => {
    if (data && currentAyahIndex === -1) {
        window.scrollTo(0, 0);
    }
  }, [data]);

  // Check if audio is already cached
  const checkOfflineAvailability = async (surahData: CombinedSurahData) => {
    if (!('caches' in window)) return;

    try {
        const cache = await caches.open('quran-audio-v1');
        const audioUrls = surahData.arabicAyahs.map(a => a.audio).filter(Boolean) as string[];

        // Check a random sample to guess availability (checking all is expensive on init)
        // Or checking all if list is small. Let's check all but efficiently.
        let cachedCount = 0;
        const checks = audioUrls.map(url => cache.match(url).then(res => res ? 1 : 0));
        const results = await Promise.all(checks);
        const totalCached = results.reduce((a: number, b: number) => a + b, 0);

        if (totalCached === audioUrls.length && audioUrls.length > 0) {
            setIsOfflineReady(true);
        }
    } catch (e) {
        console.error("Cache check failed", e);
    }
  };

  const handleDownloadSurah = async () => {
    if (!data || downloading) return;
    setDownloading(true);
    setDownloadProgress(0);

    const audioUrls = data.arabicAyahs.map(a => a.audio).filter(Boolean) as string[];
    const total = audioUrls.length;
    let completed = 0;

    try {
        // Use a concurrency limit to avoid browser blocking
        const limit = 5;
        const queue = [...audioUrls];

        const worker = async () => {
             while(queue.length > 0) {
                 const url = queue.shift();
                 if(!url) break;
                 try {
                     await fetch(url); // Trigger Service Worker Cache
                     completed++;
                     setDownloadProgress(Math.round((completed / total) * 100));
                 } catch (e) {
                     console.error("Failed to fetch", url);
                 }
             }
        };

        const workers = Array(Math.min(limit, total)).fill(null).map(() => worker());
        await Promise.all(workers);

        setIsOfflineReady(true);
    } catch (e) {
        console.error("Download failed", e);
    } finally {
        setDownloading(false);
    }
  };

  // Handle Audio Playback
  useEffect(() => {
    if (currentAyahIndex !== -1 && audioRef.current && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];
      if (ayah?.audio) {
        audioRef.current.src = ayah.audio;
        audioRef.current.play().catch(e => {
            console.error("Playback failed", e);
            setIsPlaying(false);
        });
        setIsPlaying(true);

        const element = document.getElementById(`ayah-${ayah.number}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            const elementPosition = element.getBoundingClientRect().top + window.scrollY;
            const offsetPosition = elementPosition - headerHeight - 20;

            window.scrollTo({
                top: offsetPosition,
                behavior: 'smooth'
            });
        }
      }
    } else if (currentAyahIndex === -1 && audioRef.current) {
        audioRef.current.pause();
        setIsPlaying(false);
    }
  }, [currentAyahIndex, data]);

  const togglePlaySurah = () => {
    if (isPlaying) {
        audioRef.current?.pause();
        setIsPlaying(false);
    } else {
        if (currentAyahIndex === -1) {
            setCurrentAyahIndex(0);
        } else {
            audioRef.current?.play();
            setIsPlaying(true);
        }
    }
  };

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const playSpecificAyah = (index: number) => {
    if (currentAyahIndex === index && isPlaying) {
        audioRef.current?.pause();
        setIsPlaying(false);
    } else {
        setCurrentAyahIndex(index);
        setIsPlaying(true);
    }
  };

  if (loading) return <LoadingSpinner />;
  if (error || !data) return (
    <div className="flex flex-col items-center justify-center min-h-[50vh] text-center px-4">
      <div className="text-red-500 text-xl mb-4">Error loading content</div>
      <p className="text-gray-600 mb-6">{error}</p>
      <button 
        onClick={onBack}
        className="flex items-center px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
      >
        <ArrowLeft size={18} className="mr-2" />
        Go Back
      </button>
    </div>
  );

  const { surahInfo, arabicAyahs, urduAyahs } = data;

  return (
    <div className="min-h-screen bg-paper pb-20 relative">
      <audio 
        ref={audioRef} 
        onEnded={handleAyahEnd}
        onError={() => {
            console.error("Audio error");
            setIsPlaying(false);
        }}
      />

       {/* Sticky Header */}
      <div 
        ref={headerRef}
        className="sticky top-0 z-30 bg-paper/95 backdrop-blur-sm border-b border-emerald-100 shadow-sm transition-all duration-300"
      >
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button 
                    onClick={onBack}
                    className="p-2 text-emerald-800 hover:bg-emerald-100 rounded-full transition-colors mr-2"
                    aria-label="Back to List"
                >
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                    <h1 className="text-xl font-arabic font-bold text-emerald-900">{surahInfo.name}</h1>
                </div>
            </div>

            {/* Player Controls in Header */}
            <div className="flex items-center space-x-1 md:space-x-4">

                 {/* Download Button */}
                 <button 
                    onClick={handleDownloadSurah}
                    disabled={isOfflineReady || downloading}
                    className={`flex items-center justify-center px-3 py-1.5 rounded-full text-xs md:text-sm font-medium transition-all ${
                        isOfflineReady 
                        ? 'bg-emerald-100 text-emerald-700 cursor-default'
                        : downloading 
                            ? 'bg-gold-100 text-gold-700 cursor-wait'
                            : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'
                    }`}
                 >
                    {isOfflineReady ? (
                        <>
                            <CheckCircle size={16} className="mr-1.5" />
                            <span className="hidden md:inline">Offline Ready</span>
                        </>
                    ) : downloading ? (
                        <>
                            <Loader2 size={16} className="mr-1.5 animate-spin" />
                            <span>{downloadProgress}%</span>
                        </>
                    ) : (
                        <>
                            <Download size={16} className="mr-1.5" />
                            <span className="hidden md:inline">Download</span>
                        </>
                    )}
                 </button>

                 <div className="h-6 w-px bg-emerald-200 mx-2 hidden md:block"></div>

                 <div className="flex items-center space-x-2 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
                    <button 
                        onClick={() => {
                            if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1);
                        }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1 md:p-2 text-emerald-700 hover:text-emerald-900 disabled:opacity-30 transition-colors"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>

                    <button 
                        onClick={togglePlaySurah}
                        className={`w-8 h-8 md:w-10 md:h-10 flex items-center justify-center rounded-full text-white shadow-md transition-all ${
                            isPlaying ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-emerald-500 hover:bg-emerald-600'
                        }`}
                    >
                        {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
                    </button>

                    <button 
                        onClick={() => {
                            if(currentAyahIndex < arabicAyahs.length - 1) setCurrentAyahIndex(prev => prev + 1);
                        }}
                        disabled={currentAyahIndex >= arabicAyahs.length - 1}
                        className="p-1 md:p-2 text-emerald-700 hover:text-emerald-900 disabled:opacity-30 transition-colors"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
        {/* Mobile Title Sub-header */}
        <div className="md:hidden pb-2 text-center border-t border-emerald-50/50">
             <h1 className="text-lg font-arabic font-bold text-emerald-900 mt-1">{surahInfo.name}</h1>
             <p className="text-[10px] text-emerald-600 uppercase">{surahInfo.englishName}</p>
        </div>
      </div>

      <div className="w-full px-2 md:px-6 py-8">

        {/* Bismillah */}
        <div className="flex justify-center mb-12 mt-4">
            <div className="relative p-8">
                <img 
                    src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" 
                    alt="Bismillah" 
                    className="w-64 md:w-80 h-auto opacity-90 mx-auto"
                />
            </div>
        </div>

        {/* Verses */}
        <div className="space-y-8">
            {arabicAyahs.map((ayah, index) => {
                const urduAyah = urduAyahs[index];
                const isCurrentAyah = currentAyahIndex === index;

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.number}`}
                        className={`group relative border rounded-2xl p-6 transition-all duration-500 ${
                            isCurrentAyah 
                                ? 'bg-emerald-50 border-emerald-200 shadow-md transform scale-[1.01]' 
                                : 'bg-white border-emerald-50 shadow-sm hover:shadow-md'
                        }`}
                    >
                        <div className={`absolute -top-3 -left-3 md:-left-4 w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center text-xs md:text-sm font-bold border-2 border-white shadow-sm transition-colors ${
                            isCurrentAyah ? 'bg-emerald-600 text-white' : 'bg-emerald-100 text-emerald-800'
                        }`}>
                            {ayah.numberInSurah}
                        </div>

                        <button
                            onClick={() => playSpecificAyah(index)}
                            className={`absolute top-4 left-4 p-2 rounded-full transition-all ${
                                isCurrentAyah && isPlaying
                                    ? 'bg-emerald-100 text-emerald-700' 
                                    : 'bg-transparent text-gray-300 hover:text-emerald-500'
                            }`}
                            aria-label="Play this verse"
                        >
                            {isCurrentAyah && isPlaying ? <Volume2 size={20} className="animate-pulse" /> : <Play size={20} />}
                        </button>

                        <div className="text-right mb-6 pt-2" dir="rtl">
                            <p className={`font-arabic text-3xl md:text-4xl leading-[2.5] text-justify ${isCurrentAyah ? 'text-emerald-900' : 'text-gray-900'}`}>
                                {ayah.text} 
                                <span className="text-gold-500 text-2xl mx-2 font-arabic">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-r from-transparent via-emerald-100 to-transparent my-4"></div>

                        <div className="text-right" dir="rtl">
                            <p className={`font-urdu text-xl md:text-2xl leading-relaxed ${isCurrentAyah ? 'text-gray-900' : 'text-gray-700'}`}>
                                {urduAyah ? urduAyah.text : 'Translation loading...'}
                            </p>
                        </div>

                        <div className="mt-4 flex justify-end opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                            <button 
                                className="text-xs text-emerald-600 flex items-center hover:underline"
                                onClick={() => {
                                   navigator.clipboard.writeText(`${ayah.text}\n\n${urduAyah?.text}`);
                                }}
                            >
                                <BookOpen size={14} className="mr-1" /> Copy Verse
                            </button>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <AIChat context={`User is currently reading Surah ${surahInfo.englishName} (${surahInfo.name}). ${isPlaying ? `They are listening to verse ${currentAyahIndex + 1}.` : ''}`} />
    </div>
  );
};

export default Reader;

export interface Surah {
  number: number;
  name: string;
  englishName: string;
  englishNameTranslation: string;
  numberOfAyahs: number;
  revelationType: string;
}

export interface Ayah {
  number: number;
  text: string;
  numberInSurah: number;
  juz: number;
  manzil: number;
  page: number;
  ruku: number;
  hizbQuarter: number;
  sajda: boolean | { id: number; recommended: boolean; obligatory: boolean };
  audio?: string;
}

export interface SurahDetail {
  number: number;
  name: string;
  englishName: string;
  englishNameTranslation: string;
  revelationType: string;
  numberOfAyahs: number;
  ayahs: Ayah[];
  edition?: {
    identifier: string;
    language: string;
    name: string;
    englishName: string;
    format: string;
    type: string;
  };
}

export interface CombinedSurahData {
  surahInfo: Surah;
  arabicAyahs: Ayah[];
  urduAyahs: Ayah[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  isError?: boolean;
}

export interface Bookmark {
  surahNumber: number;
  ayahNumber: number; // numberInSurah
  surahName: string;
  timestamp: number;
}

import React, { useEffect, useState, useRef } from 'react';
import { ArrowLeft, BookOpen, Share2, Play, Pause, SkipForward, SkipBack, Volume2, Download, CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck } from 'lucide-react';
import { CombinedSurahData, Bookmark } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  // Offline/Download States
  const [downloading, setDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState(0);
  const [isOfflineReady, setIsOfflineReady] = useState(false);

  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Load bookmarks
  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) {
      setBookmarks(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    let isMounted = true;

    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsOfflineReady(false);

      try {
        const result = await getSurahDetails(surahNumber);
        if (isMounted) {
          setData(result);
          checkOfflineAvailability(result);

          // Handle initial scroll to ayah if coming from bookmark
          if (initialAyah) {
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    const elementPosition = element.getBoundingClientRect().top + window.scrollY;
                    const offsetPosition = elementPosition - headerHeight - 20;
                    window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
                }
            }, 500);
          }
        }
      } catch (err) {
        if (isMounted) {
          setError('Failed to load Surah. Please check your internet connection.');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, initialAyah]);

  useEffect(() => {
    if (data && currentAyahIndex === -1 && !initialAyah) {
        window.scrollTo(0, 0);
    }
  }, [data, initialAyah]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;

    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    let updated: Bookmark[];

    if (isBookmarked) {
        updated = bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah));
    } else {
        const newBookmark: Bookmark = {
            surahNumber,
            ayahNumber: ayahNumberInSurah,
            surahName: data.surahInfo.englishName,
            timestamp: Date.now()
        };
        updated = [newBookmark, ...bookmarks];
    }

    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const checkIsBookmarked = (ayahNumberInSurah: number) => {
    return bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
  };

  // Check if audio is already cached
  const checkOfflineAvailability = async (surahData: CombinedSurahData) => {
    if (!('caches' in window)) return;

    try {
        const cache = await caches.open('quran-audio-v1');
        const audioUrls = surahData.arabicAyahs.map(a => a.audio).filter(Boolean) as string[];

        let cachedCount = 0;
        const checks = audioUrls.map(url => cache.match(url).then(res => res ? 1 : 0));
        const results = await Promise.all(checks);
        const totalCached = results.reduce((a: number, b: number) => a + b, 0);

        if (totalCached === audioUrls.length && audioUrls.length > 0) {
            setIsOfflineReady(true);
        }
    } catch (e) {
        console.error("Cache check failed", e);
    }
  };

  const handleDownloadSurah = async () => {
    if (!data || downloading) return;
    setDownloading(true);
    setDownloadProgress(0);

    const audioUrls = data.arabicAyahs.map(a => a.audio).filter(Boolean) as string[];
    const total = audioUrls.length;
    let completed = 0;

    try {
        const limit = 5;
        const queue = [...audioUrls];
        const worker = async () => {
             while(queue.length > 0) {
                 const url = queue.shift();
                 if(!url) break;
                 try {
                     await fetch(url);
                     completed++;
                     setDownloadProgress(Math.round((completed / total) * 100));
                 } catch (e) {
                     console.error("Failed to fetch", url);
                 }
             }
        };
        const workers = Array(Math.min(limit, total)).fill(null).map(() => worker());
        await Promise.all(workers);
        setIsOfflineReady(true);
    } catch (e) {
        console.error("Download failed", e);
    } finally {
        setDownloading(false);
    }
  };

  // Handle Audio Playback
  useEffect(() => {
    if (currentAyahIndex !== -1 && audioRef.current && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];
      if (ayah?.audio) {
        audioRef.current.src = ayah.audio;
        audioRef.current.play().catch(e => {
            console.error("Playback failed", e);
            setIsPlaying(false);
        });
        setIsPlaying(true);

        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            const elementPosition = element.getBoundingClientRect().top + window.scrollY;
            const offsetPosition = elementPosition - headerHeight - 20;
            window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
        }
      }
    } else if (currentAyahIndex === -1 && audioRef.current) {
        audioRef.current.pause();
        setIsPlaying(false);
    }
  }, [currentAyahIndex, data]);

  const togglePlaySurah = () => {
    if (isPlaying) {
        audioRef.current?.pause();
        setIsPlaying(false);
    } else {
        if (currentAyahIndex === -1) {
            setCurrentAyahIndex(0);
        } else {
            audioRef.current?.play();
            setIsPlaying(true);
        }
    }
  };

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const playSpecificAyah = (index: number) => {
    if (currentAyahIndex === index && isPlaying) {
        audioRef.current?.pause();
        setIsPlaying(false);
    } else {
        setCurrentAyahIndex(index);
        setIsPlaying(true);
    }
  };

  if (loading) return <LoadingSpinner />;
  if (error || !data) return (
    <div className="flex flex-col items-center justify-center min-h-[50vh] text-center px-4">
      <div className="text-red-500 text-xl mb-4">Error loading content</div>
      <p className="text-gray-600 mb-6">{error}</p>
      <button 
        onClick={onBack}
        className="flex items-center px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
      >
        <ArrowLeft size={18} className="mr-2" />
        Go Back
      </button>
    </div>
  );

  const { surahInfo, arabicAyahs, urduAyahs } = data;

  return (
    <div className="min-h-screen bg-paper pb-20 relative">
      <audio 
        ref={audioRef} 
        onEnded={handleAyahEnd}
        onError={() => {
            console.error("Audio error");
            setIsPlaying(false);
        }}
      />

       {/* Sticky Header */}
      <div 
        ref={headerRef}
        className="sticky top-0 z-30 bg-paper/95 backdrop-blur-sm border-b border-emerald-100 shadow-sm transition-all duration-300"
      >
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button 
                    onClick={onBack}
                    className="p-2 text-emerald-800 hover:bg-emerald-100 rounded-full transition-colors mr-2"
                    aria-label="Back to List"
                >
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                    <h1 className="text-xl font-arabic font-bold text-emerald-900">{surahInfo.name}</h1>
                </div>
            </div>

            <div className="flex items-center space-x-1 md:space-x-4">
                 <button 
                    onClick={handleDownloadSurah}
                    disabled={isOfflineReady || downloading}
                    className={`flex items-center justify-center px-3 py-1.5 rounded-full text-xs md:text-sm font-medium transition-all ${
                        isOfflineReady 
                        ? 'bg-emerald-100 text-emerald-700 cursor-default'
                        : downloading 
                            ? 'bg-gold-100 text-gold-700 cursor-wait'
                            : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'
                    }`}
                 >
                    {isOfflineReady ? (
                        <>
                            <CheckCircle size={16} className="mr-1.5" />
                            <span className="hidden md:inline">Offline Ready</span>
                        </>
                    ) : downloading ? (
                        <>
                            <Loader2 size={16} className="mr-1.5 animate-spin" />
                            <span>{downloadProgress}%</span>
                        </>
                    ) : (
                        <>
                            <Download size={16} className="mr-1.5" />
                            <span className="hidden md:inline">Download</span>
                        </>
                    )}
                 </button>

                 <div className="h-6 w-px bg-emerald-200 mx-2 hidden md:block"></div>

                 <div className="flex items-center space-x-2 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
                    <button 
                        onClick={() => {
                            if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1);
                        }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1 md:p-2 text-emerald-700 hover:text-emerald-900 disabled:opacity-30 transition-colors"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>

                    <button 
                        onClick={togglePlaySurah}
                        className={`w-8 h-8 md:w-10 md:h-10 flex items-center justify-center rounded-full text-white shadow-md transition-all ${
                            isPlaying ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-emerald-500 hover:bg-emerald-600'
                        }`}
                    >
                        {isPlaying ? <Pause size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" className="ml-0.5" />}
                    </button>

                    <button 
                        onClick={() => {
                            if(currentAyahIndex < arabicAyahs.length - 1) setCurrentAyahIndex(prev => prev + 1);
                        }}
                        disabled={currentAyahIndex >= arabicAyahs.length - 1}
                        className="p-1 md:p-2 text-emerald-700 hover:text-emerald-900 disabled:opacity-30 transition-colors"
                    >
                        <SkipForward size={18} fill="currentColor" />
