                />
            </div>
        </div>

        <div className="space-y-8">
            {arabicAyahs.map((ayah, index) => {
                const urduAyah = urduAyahs[index];
                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = checkIsBookmarked(ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-2xl p-6 transition-all duration-500 ${
