                                        : 'bg-transparent text-gray-300 hover:text-gold-500'
                                }`}
                                aria-label="Bookmark this verse"
                            >
                                {bookmarked ? <BookmarkCheck size={20} fill="currentColor" /> : <BookmarkIcon size={20} />}
                            </button>
                            <button
                                onClick={() => playSpecificAyah(index)}
                                className={`p-2 rounded-full transition-all ${
                                    isCurrentAyah && isPlaying
                                        ? 'bg-emerald-100 text-emerald-700' 
                                        : 'bg-transparent text-gray-300 hover:text-emerald-500'
                                }`}
                                aria-label="Play this verse"
                            >
                                {isCurrentAyah && isPlaying ? <Volume2 size={20} className="animate-pulse" /> : <Play size={20} />}
                            </button>
                        </div>

                        <div className="text-right mb-6 pt-2" dir="rtl">
                            <p className={`font-arabic text-3xl md:text-4xl leading-[2.5] text-justify ${isCurrentAyah ? 'text-emerald-900' : 'text-gray-900'}`}>
                                {ayah.text} 
                                <span className="text-gold-500 text-2xl mx-2 font-arabic">۝</span>
