                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
