import { Surah, CombinedSurahData, SurahDetail, ScriptStyle } from '../types';

const BASE_URL = 'https://api.alquran.cloud/v1';
const LIST_CACHE_KEY = 'quran_surah_list_v3'; // Version bumped to invalidate old cache

// In-memory cache to store data for the current session (bullet speed navigation)
const memoryCache: Record<string, any> = {};

export const getSurahList = async (): Promise<Surah[]> => {
  try {
    // 1. Check Memory Cache (Fastest)
    if (memoryCache[LIST_CACHE_KEY]) {
      return memoryCache[LIST_CACHE_KEY];
    }

    // 2. Check Local Storage (Fast)
    const localData = localStorage.getItem(LIST_CACHE_KEY);
    if (localData) {
      const parsed = JSON.parse(localData);
      memoryCache[LIST_CACHE_KEY] = parsed;
      return parsed;
    }

    // 3. Network Request (Slowest - only first time)
    const response = await fetch(`${BASE_URL}/surah`);
    const data = await response.json();

    // Save to caches
    memoryCache[LIST_CACHE_KEY] = data.data;
    localStorage.setItem(LIST_CACHE_KEY, JSON.stringify(data.data));

    return data.data;
  } catch (error) {
    console.error('Error fetching surah list:', error);
    throw error;
  }
};

export const getSurahDetails = async (surahNumber: number, script: ScriptStyle = 'indopak'): Promise<CombinedSurahData> => {
  // Version bumped in cache key to force refresh for new content
  const cacheKey = `surah_${surahNumber}_${script}_v6`;

  try {
    // 1. Check Memory Cache
    if (memoryCache[cacheKey]) {
      return memoryCache[cacheKey];
    }

    // Determine script identifier
    // 'quran-indopak' is the specific edition for Pakistan/India region with full tashkeel
    const scriptId = script === 'indopak' ? 'quran-indopak' : 'quran-uthmani';

    // Fetch Arabic (Dynamic Script), English (Saheeh), Urdu (Maududi), and Audio (Mishary Rashid Alafasy)
    // Removed ur.jalandhry
    const response = await fetch(
      `${BASE_URL}/surah/${surahNumber}/editions/${scriptId},en.saheeh,ur.maududi,ar.alafasy`
    );
    const data = await response.json();

    const allEditions: SurahDetail[] = data.data;

    // The order in API response matches the order requested, but we should find by ID to be safe
    // If exact ID matches aren't found, we fallback to indices based on requested order:
    // 0: scriptId (Arabic)
    // 1: en.saheeh
    // 2: ur.maududi
    // 3: ar.alafasy

    const arabicData = allEditions.find(e => e.edition?.identifier === scriptId) || allEditions[0];
    const englishData = allEditions.find(e => e.edition?.identifier === 'en.saheeh') || allEditions[1];
    const tafseerData = allEditions.find(e => e.edition?.identifier === 'ur.maududi') || allEditions[2];
    const audioData = allEditions.find(e => e.edition?.identifier === 'ar.alafasy') || allEditions[3];

    // Merge audio URL into arabic ayahs
    const mergedArabicAyahs = arabicData.ayahs.map((ayah, index) => ({
      ...ayah,
      audio: audioData.ayahs[index]?.audio
    }));

    const result = {
      surahInfo: {
        number: arabicData.number,
        name: arabicData.name,
        englishName: arabicData.englishName,
        englishNameTranslation: arabicData.englishNameTranslation,
        numberOfAyahs: arabicData.numberOfAyahs,
        revelationType: arabicData.revelationType,
      },
      arabicAyahs: mergedArabicAyahs,
      englishAyahs: englishData.ayahs,
      tafseerAyahs: tafseerData.ayahs,
    };

    // Store in memory cache
    memoryCache[cacheKey] = result;
    return result;

  } catch (error) {
    console.error(`Error fetching surah ${surahNumber}:`, error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import SurahList from './components/SurahList';
import Reader from './components/Reader';
import AboutAuthor from './components/AboutAuthor';
import { AppSettings } from './types';

const DEFAULT_SETTINGS: AppSettings = {
  theme: 'paper',
  fontSize: 'lg',
  script: 'indopak', // Explicitly default to IndoPak
  audioMode: 'arabic',
  showEnglish: false,
  showTafseer: true // Enabled by default as it's the primary Urdu content now
};

const SETTINGS_KEY = 'quran_settings_v5'; // Version bumped

const App: React.FC = () => {
  const [view, setView] = useState<'list' | 'reader' | 'about'>('list');
  const [currentSurah, setCurrentSurah] = useState<number>(1);
  const [currentAyah, setCurrentAyah] = useState<number | undefined>(undefined);

  // Settings State
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (saved) {
      // Merge saved settings with defaults to ensure new fields are present
      return { ...DEFAULT_SETTINGS, ...JSON.parse(saved) };
    } else {
        // Try to recover old settings but merge with new defaults
        const oldSaved = localStorage.getItem('quran_settings_v4');
        if (oldSaved) {
            const old = JSON.parse(oldSaved);
            return { ...DEFAULT_SETTINGS, ...old };
        }
        return DEFAULT_SETTINGS;
    }
  });

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash === '#about') {
        setView('about');
      } else if (hash.startsWith('#surah/')) {
        const parts = hash.split('/');
        const surahNum = parseInt(parts[1], 10);
        const ayahNum = parts[2] ? parseInt(parts[2], 10) : undefined;
        if (!isNaN(surahNum)) {
          setCurrentSurah(surahNum);
          setCurrentAyah(ayahNum);
          setView('reader');
        } else {
            setView('list');
        }
      } else {
        setView('list');
      }
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const handleSelectSurah = (surahNumber: number, ayahNumber?: number) => {
    if (ayahNumber) {
        window.location.hash = `surah/${surahNumber}/${ayahNumber}`;
    } else {
        window.location.hash = `surah/${surahNumber}`;
    }
  };

  const handleBack = () => {
    window.location.hash = '';
  };

  const handleGoToAbout = () => {
    window.location.hash = 'about';
  };

  return (
    <div className={`antialiased min-h-screen font-sans selection:bg-emerald-200 selection:text-emerald-900 transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950 text-gray-100' : 
      settings.theme === 'sepia' ? 'bg-[#f4ecd8] text-[#5b4636]' : 'bg-paper text-gray-900'
    }`}>
      {view === 'list' && (
        <SurahList 
          onSelectSurah={handleSelectSurah} 
          onGoToAbout={handleGoToAbout} 
        />
      )}
      {view === 'reader' && (
        <Reader 
          surahNumber={currentSurah} 
          initialAyah={currentAyah} 
          onBack={handleBack} 
          settings={settings}
          onUpdateSettings={setSettings}
        />
      )}
      {view === 'about' && (
        <AboutAuthor 
          onBack={handleBack} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    // Lateef needs to be larger than regular fonts
    const isIndoPak = settings.script === 'indopak';

    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تحریر کا سائز (Font Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Toggles */}
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>

                {/* Script Style */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <h1 className="text-xl font-arabic font-bold text-emerald-700 hidden md:block">{data?.surahInfo.name}</h1>
            </div>

            <div className="flex items-center space-x-2">
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>

                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-[98%] mx-auto px-2 md:px-6 py-12">
        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];

                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-3xl p-6 md:p-8 transition-all duration-500 ${
                            isCurrentAyah ? 'border-emerald-400 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl' : getThemeClasses()
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Now the primary Urdu Content */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block font-sans opacity-60">Tafseer (Abul A'la Maududi)</span>
                                <p className={`font-urdu leading-[4.5] text-xl md:text-2xl ${
                                    isCurrentAyah ? 'text-gray-900 dark:text-gray-100 font-bold' : 'text-gray-600 dark:text-gray-400'
                                }`}>
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation (Optional) */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
             {/* Load More Sentinel */}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    // Lateef needs to be larger than regular fonts
    const isIndoPak = settings.script === 'indopak';

    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تحریر کا سائز (Font Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Toggles */}
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>

                {/* Script Style */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <h1 className="text-xl font-arabic font-bold text-emerald-700 hidden md:block">{data?.surahInfo.name}</h1>
            </div>

            <div className="flex items-center space-x-2">
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>

                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-[98%] mx-auto px-2 md:px-6 py-12">
        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];

                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-3xl p-6 md:p-8 transition-all duration-500 ${
                            isCurrentAyah ? 'border-emerald-400 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl' : getThemeClasses()
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Now the primary Urdu Content */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                <p className={`font-urdu leading-[4.5] text-xl md:text-2xl ${
                                    isCurrentAyah ? 'text-gray-900 dark:text-gray-100 font-bold' : 'text-gray-600 dark:text-gray-400'
                                }`}>
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation (Optional) */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
             {/* Load More Sentinel */}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} />
    </div>
  );
};

export default Reader;

import { GoogleGenAI } from "@google/genai";

// Initialize Gemini Client
const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        throw new Error("API Key not found");
    }
    return new GoogleGenAI({ apiKey });
};

export const askIslamicScholar = async (
  query: string,
  context?: string
): Promise<string> => {
  try {
    const ai = getClient();

    const systemInstruction = `
You are a knowledgeable, respectful, and gentle Islamic scholar assistant.
Your goal is to help users understand the Quran and Islamic teachings.
You primarily speak in Urdu if the user asks in Urdu, or English if asked in English.
However, since this is a Quran app with Urdu translation, favor Urdu explanations for Tafseer.
Keep answers concise, accurate, and always reference Quranic verses if possible.
Avoid controversial sectarian debates; focus on the consensus (Ijma) or general understanding.

If a context (current Surah/Ayah) is provided, use it to frame your answer.
    `;

    const model = "gemini-3-flash-preview";

    let finalPrompt = query;
    if (context) {
        finalPrompt = `Context: ${context}\n\nUser Question: ${query}`;
    }

    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.3, // Lower temperature for more factual/consistent answers
      },
    });

    return response.text || "مذرت، میں ابھی جواب دینے سے قاصر ہوں۔"; // Sorry, unable to answer right now.
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Something went wrong. Please check your API key or try again later.";
  }
};

export const fetchSurahIntroduction = async (surahName: string, surahNumber: number): Promise<string> => {
  const cacheKey = `surah_intro_${surahNumber}_v1`;
  const cached = localStorage.getItem(cacheKey);
  if (cached) return cached;

  try {
    const ai = getClient();
    const prompt = `
      Provide a comprehensive introduction for Surah ${surahName} (Chapter ${surahNumber}) based specifically on the commentary "Tafheem-ul-Quran" by Maulana Abul A'la Maududi.

      Output language: Urdu (اردو).

      Please cover the following points clearly:
      1. Period of Revelation (Is it Makki or Madani? In which year or phase of Prophethood was it revealed?)
      2. Historical Background (Conditions/Asbab al-Nuzul: What was happening in the life of the Holy Prophet (PBUH) and Muslims when this was revealed?)
      3. Central Theme (What is the main subject matter and stories discussed?)

      Format the response in clean Markdown with bold headings in Urdu. Keep the tone scholarly yet accessible.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        temperature: 0.3,
      }
    });

    const text = response.text || "";
    if (text) {
      localStorage.setItem(cacheKey, text);
    }
    return text;
  } catch (error) {
    console.error("Error fetching surah intro:", error);
    return "";
  }
};

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          // Determine if we should jump to an ayah or show intro
          if (initialAyah) {
            setShowIntro(false); // Hide intro if jumping to specific verse
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          // Fetch Background Info
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    // Lateef needs to be larger than regular fonts
    const isIndoPak = settings.script === 'indopak';

    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تحریر کا سائز (Font Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Toggles */}
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>

                {/* Script Style */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                  <p className="text-xs text-gray-500 -mt-1">{data?.surahInfo.englishName} • {data?.surahInfo.revelationType}</p>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>

                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-[98%] mx-auto px-2 md:px-6 py-12">
        {/* Surah Introduction Card */}
        {showIntro && (
          <div className={`mb-12 rounded-3xl p-6 md:p-8 relative overflow-hidden transition-all ${
            settings.theme === 'dark' ? 'bg-emerald-950/40 border border-emerald-900' : 'bg-emerald-50/60 border border-emerald-100'
          }`}>
             <div className="flex justify-between items-start mb-6 border-b border-emerald-200/50 pb-4">
                <h2 className="text-2xl font-bold font-arabic text-emerald-800 dark:text-emerald-400">سورة کا تعارف (Introduction)</h2>
                <div className="bg-emerald-200 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200 text-xs px-2 py-1 rounded font-bold uppercase tracking-widest flex items-center">
                   <Info size={14} className="mr-1" />
                   Tafheem-ul-Quran
                </div>
             </div>

             {loadingIntro ? (
                <div className="space-y-4 animate-pulse">
                   <div className="h-4 bg-emerald-200/50 rounded w-3/4"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-full"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-5/6"></div>
                </div>
             ) : surahIntro ? (
                <div className={`prose max-w-none font-urdu leading-loose text-justify ${settings.theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                   <div className="whitespace-pre-wrap">{surahIntro}</div>
                </div>
             ) : (
                <div className="text-center py-4 text-gray-500 italic">
                  Background information could not be loaded. Please check internet connection.
                </div>
             )}
          </div>
        )}

        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];

                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-3xl p-6 md:p-8 transition-all duration-500 ${
                            isCurrentAyah ? 'border-emerald-400 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl' : getThemeClasses()
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Now the primary Urdu Content */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                {/* Removed Heading, Increased Line Height to leading-[5.5] */}
                                <p className={`font-urdu leading-[5.5] text-xl md:text-2xl ${
                                    isCurrentAyah ? 'text-gray-900 dark:text-gray-100 font-bold' : 'text-gray-600 dark:text-gray-400'
                                }`}>
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation (Optional) */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
             {/* Load More Sentinel */}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} />
    </div>
  );
};

export default Reader;

export interface Surah {
  number: number;
  name: string;
  englishName: string;
  englishNameTranslation: string;
  numberOfAyahs: number;
  revelationType: string;
}

