  arabicAyahs: Ayah[];
  englishAyahs: Ayah[];
  tafseerAyahs: Ayah[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  isError?: boolean;
}

export interface Bookmark {
  surahNumber: number;
  ayahNumber: number; // numberInSurah
  surahName: string;
  timestamp: number;
}

export type ThemeType = 'paper' | 'dark' | 'sepia';
export type FontSize = 'sm' | 'base' | 'lg' | 'xl' | '2xl';
export type ScriptStyle = 'uthmani' | 'indopak';
export type AudioMode = 'arabic';

export interface AppSettings {
  theme: ThemeType;
  fontSize: FontSize;
  tafseerFontSize: FontSize;
  script: ScriptStyle;
  audioMode: AudioMode;
  showEnglish: boolean;
  showTafseer: boolean;
}

import React, { useState, useEffect } from 'react';
import SurahList from './components/SurahList';
import Reader from './components/Reader';
import AboutAuthor from './components/AboutAuthor';
import { AppSettings } from './types';

const DEFAULT_SETTINGS: AppSettings = {
  theme: 'paper',
  fontSize: 'lg',
  tafseerFontSize: 'lg', // Default for Urdu Tafseer
  script: 'indopak', // Explicitly default to IndoPak
  audioMode: 'arabic',
  showEnglish: false,
  showTafseer: true // Enabled by default as it's the primary Urdu content now
};

const SETTINGS_KEY = 'quran_settings_v6'; // Version bumped to v6

const App: React.FC = () => {
  const [view, setView] = useState<'list' | 'reader' | 'about'>('list');
  const [currentSurah, setCurrentSurah] = useState<number>(1);
  const [currentAyah, setCurrentAyah] = useState<number | undefined>(undefined);

  // Settings State
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (saved) {
      // Merge saved settings with defaults to ensure new fields are present
      return { ...DEFAULT_SETTINGS, ...JSON.parse(saved) };
    } else {
        // Try to recover old settings but merge with new defaults
        const oldSaved = localStorage.getItem('quran_settings_v5');
        if (oldSaved) {
            const old = JSON.parse(oldSaved);
            return { ...DEFAULT_SETTINGS, ...old };
        }
        return DEFAULT_SETTINGS;
    }
  });

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash === '#about') {
        setView('about');
      } else if (hash.startsWith('#surah/')) {
        const parts = hash.split('/');
        const surahNum = parseInt(parts[1], 10);
        const ayahNum = parts[2] ? parseInt(parts[2], 10) : undefined;
        if (!isNaN(surahNum)) {
          setCurrentSurah(surahNum);
          setCurrentAyah(ayahNum);
          setView('reader');
        } else {
            setView('list');
        }
      } else {
        setView('list');
      }
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const handleSelectSurah = (surahNumber: number, ayahNumber?: number) => {
    if (ayahNumber) {
        window.location.hash = `surah/${surahNumber}/${ayahNumber}`;
    } else {
        window.location.hash = `surah/${surahNumber}`;
    }
  };

  const handleBack = () => {
    window.location.hash = '';
  };

  const handleGoToAbout = () => {
    window.location.hash = 'about';
  };

  return (
    <div className={`antialiased min-h-screen font-sans selection:bg-emerald-200 selection:text-emerald-900 transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950 text-gray-100' : 
      settings.theme === 'sepia' ? 'bg-[#f4ecd8] text-[#5b4636]' : 'bg-paper text-gray-900'
    }`}>
      {view === 'list' && (
        <SurahList 
          onSelectSurah={handleSelectSurah} 
          onGoToAbout={handleGoToAbout} 
        />
      )}
      {view === 'reader' && (
        <Reader 
          surahNumber={currentSurah} 
          initialAyah={currentAyah} 
          onBack={handleBack} 
          settings={settings}
          onUpdateSettings={setSettings}
        />
      )}
      {view === 'about' && (
        <AboutAuthor 
          onBack={handleBack} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          // Determine if we should jump to an ayah or show intro
          if (initialAyah) {
            setShowIntro(false); // Hide intro if jumping to specific verse
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          // Fetch Background Info
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    // Lateef needs to be larger than regular fonts
    const isIndoPak = settings.script === 'indopak';

    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerFontClasses = () => {
    // Noto Nastaliq Urdu scale
    switch(settings.tafseerFontSize) {
      case 'sm': return 'text-lg md:text-xl leading-[4.0]';
      case 'base': return 'text-xl md:text-2xl leading-[4.5]';
      case 'lg': return 'text-2xl md:text-3xl leading-[5.5]';
      case 'xl': return 'text-3xl md:text-4xl leading-[6.0]';
      case '2xl': return 'text-4xl md:text-5xl leading-[7.0]';
      default: return 'text-2xl md:text-3xl leading-[5.5]';
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Arabic Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Tafseer Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تفسیر سائز (Tafseer Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, tafseerFontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.tafseerFontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Toggles */}
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>

                {/* Script Style */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                  <p className="text-xs text-gray-500 -mt-1">{data?.surahInfo.englishName} • {data?.surahInfo.revelationType}</p>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>

                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-[98%] mx-auto px-2 md:px-6 py-12">
        {/* Surah Introduction Card */}
        {showIntro && (
          <div className={`mb-12 rounded-3xl p-6 md:p-8 relative overflow-hidden transition-all ${
            settings.theme === 'dark' ? 'bg-emerald-950/40 border border-emerald-900' : 'bg-emerald-50/60 border border-emerald-100'
          }`}>
             <div className="flex justify-between items-start mb-6 border-b border-emerald-200/50 pb-4">
                <h2 className="text-2xl font-bold font-arabic text-emerald-800 dark:text-emerald-400">سورة کا تعارف (Introduction)</h2>
                <div className="bg-emerald-200 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200 text-xs px-2 py-1 rounded font-bold uppercase tracking-widest flex items-center">
                   <Info size={14} className="mr-1" />
                   Tafheem-ul-Quran
                </div>
             </div>

             {loadingIntro ? (
                <div className="space-y-4 animate-pulse">
                   <div className="h-4 bg-emerald-200/50 rounded w-3/4"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-full"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-5/6"></div>
                </div>
             ) : surahIntro ? (
                <div className={`prose max-w-none font-urdu leading-loose text-justify ${settings.theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                   <div className="whitespace-pre-wrap">{surahIntro}</div>
                </div>
             ) : (
                <div className="text-center py-4 text-gray-500 italic">
                  Background information could not be loaded. Please check internet connection.
                </div>
             )}
          </div>
        )}

        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];

                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-3xl p-6 md:p-8 transition-all duration-500 ${
                            isCurrentAyah ? 'border-emerald-400 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl' : getThemeClasses()
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Now the primary Urdu Content */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                {/* Removed Heading, Applied dynamic classes via getTafseerFontClasses() */}
                                <p className={`font-urdu ${getTafseerFontClasses()} ${
                                    isCurrentAyah ? 'text-gray-900 dark:text-gray-100 font-bold' : 'text-gray-600 dark:text-gray-400'
                                }`}>
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation (Optional) */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
             {/* Load More Sentinel */}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          // Determine if we should jump to an ayah or show intro
          if (initialAyah) {
            setShowIntro(false); // Hide intro if jumping to specific verse
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          // Fetch Background Info
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    // Lateef needs to be larger than regular fonts
    const isIndoPak = settings.script === 'indopak';

    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  // Using inline styles for Tafseer to guarantee line-height and font-size application
  const getTafseerStyle = () => {
    // Large, readable base sizes for Nastaliq
    switch(settings.tafseerFontSize) {
      case 'sm': return { fontSize: '1.4rem', lineHeight: '2.8rem' }; 
      case 'base': return { fontSize: '1.6rem', lineHeight: '3.2rem' };
      case 'lg': return { fontSize: '2.0rem', lineHeight: '4.0rem' }; // Default
      case 'xl': return { fontSize: '2.4rem', lineHeight: '4.8rem' };
      case '2xl': return { fontSize: '3.0rem', lineHeight: '6.0rem' };
      default: return { fontSize: '2.0rem', lineHeight: '4.0rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Arabic Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Tafseer Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اردو ترجمہ سائز (Urdu Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, tafseerFontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.tafseerFontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Toggles */}
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>

                {/* Script Style */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                  <p className="text-xs text-gray-500 -mt-1">{data?.surahInfo.englishName} • {data?.surahInfo.revelationType}</p>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>

                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-[98%] mx-auto px-2 md:px-6 py-12">
        {/* Surah Introduction Card */}
        {showIntro && (
          <div className={`mb-12 rounded-3xl p-6 md:p-8 relative overflow-hidden transition-all ${
            settings.theme === 'dark' ? 'bg-emerald-950/40 border border-emerald-900' : 'bg-emerald-50/60 border border-emerald-100'
          }`}>
             <div className="flex justify-between items-start mb-6 border-b border-emerald-200/50 pb-4">
                <h2 className="text-2xl font-bold font-arabic text-emerald-800 dark:text-emerald-400">سورة کا تعارف (Introduction)</h2>
                <div className="bg-emerald-200 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200 text-xs px-2 py-1 rounded font-bold uppercase tracking-widest flex items-center">
                   <Info size={14} className="mr-1" />
                   Tafheem-ul-Quran
                </div>
             </div>

             {loadingIntro ? (
                <div className="space-y-4 animate-pulse">
                   <div className="h-4 bg-emerald-200/50 rounded w-3/4"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-full"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-5/6"></div>
                </div>
             ) : surahIntro ? (
                <div className={`prose max-w-none font-urdu leading-loose text-justify ${settings.theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                   <div className="whitespace-pre-wrap">{surahIntro}</div>
                </div>
             ) : (
                <div className="text-center py-4 text-gray-500 italic">
                  Background information could not be loaded. Please check internet connection.
                </div>
             )}
          </div>
        )}

        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];

                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-3xl p-6 md:p-8 transition-all duration-500 ${
                            isCurrentAyah ? 'border-emerald-400 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl' : getThemeClasses()
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Now the primary Urdu Content */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                {/* Applied inline styles for guaranteed font metrics */}
                                <p 
                                    className={`font-urdu ${
                                        isCurrentAyah ? 'text-gray-900 dark:text-gray-100 font-bold' : 'text-gray-600 dark:text-gray-400'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation (Optional) */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
             {/* Load More Sentinel */}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} />
    </div>
  );
};

export default Reader;

import React, { useState, useRef, useEffect } from 'react';
import { Send, X, MessageCircle, Sparkles } from 'lucide-react';
import { askIslamicScholar } from '../services/geminiService';
import { ChatMessage } from '../types';

interface AIChatProps {
  context?: string; // Current Surah context
  isOpen: boolean;
  onClose: () => void;
}

const AIChat: React.FC<AIChatProps> = ({ context, isOpen, onClose }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: 'السلام علیکم! میں آپ کا قرآن اسسٹنٹ ہوں۔ آپ کسی بھی آیت یا سورت کے بارے میں سوال پوچھ سکتے ہیں۔ (Assalam-o-Alaikum! I am your Quran Assistant. You can ask about any Ayah or Surah.)',
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await askIslamicScholar(userMessage.text, context);
      const aiMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
      };
      setMessages((prev) => [...prev, aiMessage]);
    } catch (error) {
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: 'معذرت، کچھ غلط ہو گیا۔ براہ کرم دوبارہ کوشش کریں۔',
        isError: true,
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      {/* Overlay for mobile to close when clicking outside */}
      {isOpen && (
        <div 
            className="fixed inset-0 bg-black/20 backdrop-blur-sm z-40 md:hidden"
            onClick={onClose}
        ></div>
      )}

      {/* Chat Window */}
      <div
        className={`fixed bottom-0 right-0 md:bottom-6 md:right-6 w-full md:w-96 bg-white md:rounded-2xl rounded-t-2xl shadow-2xl border border-gray-100 z-50 transform transition-all duration-300 origin-bottom-right flex flex-col ${
          isOpen ? 'translate-y-0 opacity-100' : 'translate-y-full opacity-0 pointer-events-none'
        }`}
        style={{ height: '500px', maxHeight: '80vh' }}
      >
        {/* Header */}
        <div className="bg-emerald-600 p-4 md:rounded-t-2xl rounded-t-2xl flex items-center justify-between">
          <div className="flex items-center space-x-2 space-x-reverse text-white">
            <Sparkles size={20} className="text-gold-400" />
            <h3 className="font-bold text-lg">قرآن اسسٹنٹ (AI)</h3>
          </div>
          <button onClick={onClose} className="text-white/80 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-paper bg-opacity-50">
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap ${
                  msg.role === 'user'
                    ? 'bg-emerald-600 text-white rounded-br-none'
                    : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'
                } ${msg.isError ? 'bg-red-50 border-red-200 text-red-600' : ''}`}
                dir="auto"
              >
                {msg.text}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white border border-gray-200 p-3 rounded-2xl rounded-bl-none shadow-sm flex items-center space-x-2 space-x-reverse">
                <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce delay-100" />
                <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce delay-200" />
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 border-t border-gray-100 bg-white md:rounded-b-2xl">
          <div className="flex items-center space-x-2 space-x-reverse">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="سوال پوچھیں..."
              className="flex-1 border border-gray-300 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-emerald-500 text-right font-urdu placeholder:font-sans"
              dir="rtl"
            />
            <button
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="bg-emerald-600 text-white p-2 rounded-full hover:bg-emerald-700 disabled:opacity-50 transition-colors"
            >
              <Send size={20} className={isLoading ? 'opacity-0' : ''} />
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default AIChat;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          // Determine if we should jump to an ayah or show intro
          if (initialAyah) {
            setShowIntro(false); // Hide intro if jumping to specific verse
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          // Fetch Background Info
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            const headerHeight = headerRef.current?.offsetHeight || 80;
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    // Lateef needs to be larger than regular fonts
    const isIndoPak = settings.script === 'indopak';

    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  // Using inline styles for Tafseer to guarantee line-height and font-size application
  const getTafseerStyle = () => {
    // Large, readable base sizes for Nastaliq
    switch(settings.tafseerFontSize) {
      case 'sm': return { fontSize: '1.4rem', lineHeight: '2.8rem' }; 
      case 'base': return { fontSize: '1.6rem', lineHeight: '3.2rem' };
      case 'lg': return { fontSize: '2.0rem', lineHeight: '4.0rem' }; // Default
      case 'xl': return { fontSize: '2.4rem', lineHeight: '4.8rem' };
      case '2xl': return { fontSize: '3.0rem', lineHeight: '6.0rem' };
      default: return { fontSize: '2.0rem', lineHeight: '4.0rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Arabic Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Tafseer Font Size Selection */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اردو ترجمہ سائز (Urdu Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, tafseerFontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.tafseerFontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>

                {/* Content Toggles */}
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>

                {/* Script Style */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                  <p className="text-xs text-gray-500 -mt-1">{data?.surahInfo.englishName} • {data?.surahInfo.revelationType}</p>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                 <button 
                    onClick={() => setShowChat(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm flex items-center justify-center"
                    title="Ask AI Assistant"
                >
                    <Sparkles size={20} />
                </button>

                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>

                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-[98%] mx-auto px-2 md:px-6 py-12">
        {/* Surah Introduction Card */}
        {showIntro && (
          <div className={`mb-12 rounded-3xl p-6 md:p-8 relative overflow-hidden transition-all ${
            settings.theme === 'dark' ? 'bg-emerald-950/40 border border-emerald-900' : 'bg-emerald-50/60 border border-emerald-100'
          }`}>
             <div className="flex justify-between items-start mb-6 border-b border-emerald-200/50 pb-4">
                <h2 className="text-2xl font-bold font-arabic text-emerald-800 dark:text-emerald-400">سورة کا تعارف (Introduction)</h2>
                <div className="bg-emerald-200 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200 text-xs px-2 py-1 rounded font-bold uppercase tracking-widest flex items-center">
                   <Info size={14} className="mr-1" />
                   Tafheem-ul-Quran
                </div>
             </div>

             {loadingIntro ? (
                <div className="space-y-4 animate-pulse">
                   <div className="h-4 bg-emerald-200/50 rounded w-3/4"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-full"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-5/6"></div>
                </div>
             ) : surahIntro ? (
                <div className={`prose max-w-none font-urdu leading-loose text-justify ${settings.theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                   <div className="whitespace-pre-wrap">{surahIntro}</div>
                </div>
             ) : (
                <div className="text-center py-4 text-gray-500 italic">
                  Background information could not be loaded. Please check internet connection.
                </div>
             )}
          </div>
        )}

        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];

                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-3xl p-6 md:p-8 transition-all duration-500 ${
                            isCurrentAyah ? 'border-emerald-400 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl' : getThemeClasses()
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-sm font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Now the primary Urdu Content */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                {/* Applied inline styles for guaranteed font metrics */}
                                <p 
                                    className={`font-urdu ${
                                        isCurrentAyah ? 'text-gray-900 dark:text-gray-100 font-bold' : 'text-gray-600 dark:text-gray-400'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation (Optional) */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
             {/* Load More Sentinel */}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default Reader;

import React, { useState, useEffect } from 'react';
import { Search, Book, Bookmark as BookmarkIcon, Clock, Trash2, Info, CheckCircle2, WifiOff, Sparkles } from 'lucide-react';
import { Surah, Bookmark } from '../types';
import { getSurahList } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface SurahListProps {
  onSelectSurah: (surahNumber: number, ayahNumber?: number) => void;
  onGoToAbout: () => void;
}

const SurahList: React.FC<SurahListProps> = ({ onSelectSurah, onGoToAbout }) => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [filteredSurahs, setFilteredSurahs] = useState<Surah[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const list = await getSurahList();
        setSurahs(list);
        setFilteredSurahs(list);

        const saved = localStorage.getItem('quran_bookmarks');
        if (saved) setBookmarks(JSON.parse(saved));
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const lowerSearch = search.toLowerCase();
    const filtered = surahs.filter(
      (s) =>
        s.englishName.toLowerCase().includes(lowerSearch) ||
        s.englishNameTranslation.toLowerCase().includes(lowerSearch) ||
        s.number.toString().includes(lowerSearch)
    );
    setFilteredSurahs(filtered);
  }, [search, surahs]);

  const deleteBookmark = (e: React.MouseEvent, ts: number) => {
    e.stopPropagation();
    const updated = bookmarks.filter(b => b.timestamp !== ts);
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen bg-paper">
      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Browsing Offline
        </div>
      )}

      {/* Hero Section */}
      <div className="bg-emerald-900 text-white pt-12 pb-24 px-6 relative overflow-hidden">
        {/* Decorative Background Elements */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-emerald-800 rounded-full mix-blend-multiply filter blur-3xl opacity-30 -translate-y-1/2 translate-x-1/2"></div>
        <div className="absolute top-0 left-0 w-96 h-96 bg-emerald-800 rounded-full mix-blend-multiply filter blur-3xl opacity-30 -translate-y-1/2 -translate-x-1/2"></div>

        <div className="max-w-4xl mx-auto text-center relative z-10">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-2">
                 <button onClick={() => setShowChat(true)} className="flex items-center gap-1 bg-emerald-800/50 text-emerald-100 hover:text-white hover:bg-emerald-700/50 px-3 py-2 rounded-full transition-all text-sm font-medium border border-emerald-700">
                    <Sparkles size={16} className="text-gold-400" />
                    <span>AI Scholar</span>
                </button>
            </div>
            <div>
              <h1 className="font-arabic text-5xl md:text-6xl mb-2 text-gold-400 drop-shadow-lg">القرآن الكريم</h1>
              <p className="text-emerald-100 text-lg md:text-xl font-light tracking-wider">The Holy Quran 2026</p>
            </div>
            <button onClick={onGoToAbout} className="p-2 text-emerald-300 hover:text-white transition-colors bg-emerald-800/50 rounded-full">
              <Info size={24} />
            </button>
          </div>
          <div className="relative max-w-lg mx-auto">
            <input
              type="text"
              placeholder="Search Surah (e.g. Yaseen, 36)..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full py-4 px-6 pr-12 rounded-full bg-emerald-950/60 backdrop-blur-md border border-emerald-700/50 text-white placeholder-emerald-400 focus:outline-none focus:ring-2 focus:ring-gold-500 shadow-2xl transition-all"
            />
            <Search className="absolute right-4 top-1/2 transform -translate-y-1/2 text-emerald-400" size={20} />
          </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 -mt-12 relative z-20 pb-20">
        {/* Bookmarks Section */}
        {bookmarks.length > 0 && !search && (
            <div className="mb-12">
                <div className="flex items-center space-x-2 space-x-reverse mb-4 text-emerald-900 px-2">
                    <BookmarkIcon size={20} className="text-gold-500" fill="currentColor" />
                    <h2 className="text-xl font-bold">نشانی (Bookmarks)</h2>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    {bookmarks.map((b) => (
                        <div key={b.timestamp} onClick={() => onSelectSurah(b.surahNumber, b.ayahNumber)} className="bg-white border-2 border-gold-100 hover:border-gold-300 rounded-xl p-4 shadow-sm hover:shadow-md transition-all cursor-pointer relative group overflow-hidden">
                            <div className="flex justify-between items-start mb-2">
                                <div className="text-xs font-bold bg-gold-50 text-gold-700 px-2 py-0.5 rounded-full uppercase tracking-widest">Verse {b.ayahNumber}</div>
                                <button onClick={(e) => deleteBookmark(e, b.timestamp)} className="p-1 text-gray-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"><Trash2 size={16} /></button>
                            </div>
                            <h3 className="font-bold text-gray-800 text-lg">{b.surahName}</h3>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* Surah List Grid */}
        <div className="flex items-center space-x-2 space-x-reverse mb-4 text-emerald-900 px-2">
            <Book size={20} className="text-emerald-600" />
            <h2 className="text-xl font-bold">تمام سورتیں (All Surahs)</h2>
        </div>

        {loading ? (
          <div className="bg-white rounded-2xl shadow-lg p-8"><LoadingSpinner /></div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredSurahs.map((surah) => (
              <div key={surah.number} onClick={() => onSelectSurah(surah.number)} className="bg-white hover:bg-emerald-50 border border-emerald-50 hover:border-emerald-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-all duration-300 cursor-pointer group flex items-center justify-between">
                <div className="flex items-center gap-6">
                  <div className="w-12 h-12 relative flex items-center justify-center flex-shrink-0">
                     <div className="absolute inset-0 bg-emerald-100 rounded-lg transform rotate-45 group-hover:rotate-90 transition-transform duration-300"></div>
                     <span className="relative font-bold text-emerald-800">{surah.number}</span>
                  </div>
                  <div>
                    <h3 className="font-semibold text-gray-800 group-hover:text-emerald-900 flex items-center">
                        {surah.englishName}
                    </h3>
                    <p className="text-xs text-gray-500 uppercase tracking-wide">{surah.englishNameTranslation}</p>
                  </div>
                </div>
                <div className="text-right">
                    <h3 className="font-arabic text-xl text-emerald-800 mb-1">{surah.name}</h3>
                    <p className="text-xs text-gray-400">{surah.numberOfAyahs} Verses</p>
                </div>
              </div>
