  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          // Determine if we should jump to an ayah or show intro
          if (initialAyah) {
            setShowIntro(false); // Hide intro if jumping to specific verse
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          // Fetch Background Info
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            // Center the entire card to ensure both Arabic and Urdu are visible
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    const isIndoPak = settings.script === 'indopak';
    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerStyle = () => {
    switch(settings.tafseerFontSize) {
      case 'sm': return { fontSize: '1.4rem', lineHeight: '3.0rem' }; 
      case 'base': return { fontSize: '1.6rem', lineHeight: '3.4rem' };
      case 'lg': return { fontSize: '2.0rem', lineHeight: '4.2rem' }; 
      case 'xl': return { fontSize: '2.4rem', lineHeight: '5.0rem' };
      case '2xl': return { fontSize: '3.0rem', lineHeight: '6.2rem' };
      default: return { fontSize: '2.0rem', lineHeight: '4.2rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اردو ترجمہ سائز (Urdu Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, tafseerFontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.tafseerFontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                  <p className="text-xs text-gray-500 -mt-1">{data?.surahInfo.englishName} • {data?.surahInfo.revelationType}</p>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                 <button 
                    onClick={() => setShowChat(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm flex items-center justify-center"
                    title="Ask AI Assistant"
                >
                    <Sparkles size={20} />
                </button>
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>
                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-4xl mx-auto px-2 md:px-6 py-12">
        {showIntro && (
          <div className={`mb-12 rounded-3xl p-6 md:p-8 relative overflow-hidden transition-all ${
            settings.theme === 'dark' ? 'bg-emerald-950/40 border border-emerald-900' : 'bg-emerald-50/60 border border-emerald-100'
          }`}>
             <div className="flex justify-between items-start mb-6 border-b border-emerald-200/50 pb-4">
                <h2 className="text-2xl font-bold font-arabic text-emerald-800 dark:text-emerald-400">سورة کا تعارف (Introduction)</h2>
                <div className="bg-emerald-200 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200 text-xs px-2 py-1 rounded font-bold uppercase tracking-widest flex items-center">
                   <Info size={14} className="mr-1" />
                   Tafheem-ul-Quran
                </div>
             </div>
             {loadingIntro ? (
                <div className="space-y-4 animate-pulse">
                   <div className="h-4 bg-emerald-200/50 rounded w-3/4"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-full"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-5/6"></div>
                </div>
             ) : surahIntro ? (
                <div className={`prose max-w-none font-urdu leading-loose text-justify ${settings.theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                   <div className="whitespace-pre-wrap">{surahIntro}</div>
                </div>
             ) : (
                <div className="text-center py-4 text-gray-500 italic">
                  Background information could not be loaded. Please check internet connection.
                </div>
             )}
          </div>
        )}

        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];
                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-[2rem] p-6 md:p-8 transition-all duration-500 shadow-sm ${getThemeClasses()} ${
                            isCurrentAyah ? 'border-emerald-500 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl z-10' : ''
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-xs font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - Fixed Visibility for mobile during recitation */}
                        {settings.showTafseer && tafseerAyah && (
                             <div 
                                className={`text-right transition-all duration-500 rounded-2xl p-4 md:p-6 ${
                                    isCurrentAyah 
                                        ? 'bg-emerald-50 dark:bg-emerald-950/40 border-r-4 border-emerald-500 shadow-inner' 
                                        : ''
                                }`} 
                                dir="rtl"
                             >
                                <p 
                                    className={`font-urdu ${
                                        isCurrentAyah 
                                            ? 'text-emerald-950 dark:text-emerald-50' 
                                            : 'text-gray-600 dark:text-gray-400'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          // Determine if we should jump to an ayah or show intro
          if (initialAyah) {
            setShowIntro(false); // Hide intro if jumping to specific verse
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          // Fetch Background Info
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content. Please check your connection.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  // Playback Control
  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            // Center the entire card to ensure both Arabic and Urdu are visible
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    const isIndoPak = settings.script === 'indopak';
    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerStyle = () => {
    switch(settings.tafseerFontSize) {
      case 'sm': return { fontSize: '1.4rem', lineHeight: '3.0rem' }; 
      case 'base': return { fontSize: '1.6rem', lineHeight: '3.4rem' };
      case 'lg': return { fontSize: '2.0rem', lineHeight: '4.2rem' }; 
      case 'xl': return { fontSize: '2.4rem', lineHeight: '5.0rem' };
      case '2xl': return { fontSize: '3.0rem', lineHeight: '6.2rem' };
      default: return { fontSize: '2.0rem', lineHeight: '4.2rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Offline Mode - AI Features Disabled
        </div>
      )}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>

            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button 
                                key={t}
                                onClick={() => onUpdateSettings({...settings, theme: t})}
                                className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${
                                    settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'
                                } ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}
                            >
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, fontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اردو ترجمہ سائز (Urdu Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button 
                                key={f}
                                onClick={() => onUpdateSettings({...settings, tafseerFontSize: f})}
                                className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${
                                    settings.tafseerFontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'
                                }`}
                            >
                                <Type size={f === 'sm' ? 14 : f === 'lg' ? 22 : 18} />
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                     <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">اضافی مواد (Extras)</h3>
                     <div className="space-y-3">
                        <button 
                            onClick={() => onUpdateSettings({...settings, showEnglish: !settings.showEnglish})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showEnglish ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <Languages className={`mr-3 ${settings.showEnglish ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showEnglish ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>English Translation</span>
                             </div>
                             {settings.showEnglish && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-full p-4 rounded-xl border-2 flex items-center justify-between transition-all ${
                                settings.showTafseer ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30' : 'border-gray-200 dark:border-gray-700'
                            }`}
                        >
                             <div className="flex items-center">
                                <BookOpen className={`mr-3 ${settings.showTafseer ? 'text-emerald-600' : 'text-gray-400'}`} size={20} />
                                <span className={`font-medium ${settings.showTafseer ? 'text-emerald-900 dark:text-emerald-100' : 'text-gray-500'}`}>Tafseer (Maududi)</span>
                             </div>
                             {settings.showTafseer && <CheckCircle size={18} className="text-emerald-600" />}
                        </button>
                     </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">رسم الخط (Script)</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {(['uthmani', 'indopak'] as ScriptStyle[]).map((s) => (
                            <button 
                                key={s}
                                onClick={() => onUpdateSettings({...settings, script: s})}
                                className={`p-3 rounded-xl border-2 transition-all ${
                                    settings.script === s ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-gray-200 dark:border-gray-700'
                                }`}
                            >
                                <span className="font-arabic text-lg">{s === 'uthmani' ? 'عثمانی' : 'انڈو پاک'}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                  <p className="text-xs text-gray-500 -mt-1">{data?.surahInfo.englishName} • {data?.surahInfo.revelationType}</p>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                 <button 
                    onClick={() => setShowChat(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm flex items-center justify-center"
                    title="Ask AI Assistant"
                >
                    <Sparkles size={20} />
                </button>
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"
                >
                    <SettingsIcon size={20} />
                </button>
                 <div className="flex items-center space-x-2 bg-emerald-600 p-1.5 rounded-full shadow-lg">
                    <button 
                        onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }}
                        disabled={currentAyahIndex <= 0}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipBack size={18} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => {
                            if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); }
                            else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); }
                        }}
                        className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-700 shadow-sm"
                    >
                        {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}
                    </button>
                    <button 
                        onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }}
                        disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1}
                        className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"
                    >
                        <SkipForward size={18} fill="currentColor" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-4xl mx-auto px-2 md:px-6 py-12">
        {showIntro && (
          <div className={`mb-12 rounded-3xl p-6 md:p-8 relative overflow-hidden transition-all ${
            settings.theme === 'dark' ? 'bg-emerald-950/40 border border-emerald-900' : 'bg-emerald-50/60 border border-emerald-100'
          }`}>
             <div className="flex justify-between items-start mb-6 border-b border-emerald-200/50 pb-4">
                <h2 className="text-2xl font-bold font-arabic text-emerald-800 dark:text-emerald-400">سورة کا تعارف (Introduction)</h2>
                <div className="bg-emerald-200 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200 text-xs px-2 py-1 rounded font-bold uppercase tracking-widest flex items-center">
                   <Info size={14} className="mr-1" />
                   Tafheem-ul-Quran
                </div>
             </div>
             {loadingIntro ? (
                <div className="space-y-4 animate-pulse">
                   <div className="h-4 bg-emerald-200/50 rounded w-3/4"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-full"></div>
                   <div className="h-4 bg-emerald-200/50 rounded w-5/6"></div>
                </div>
             ) : surahIntro ? (
                <div className={`prose max-w-none font-urdu leading-loose text-justify ${settings.theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                   <div className="whitespace-pre-wrap">{surahIntro}</div>
                </div>
             ) : (
                <div className="text-center py-4 text-gray-500 italic">
                  Background information could not be loaded. Please check internet connection.
                </div>
             )}
          </div>
        )}

        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];
                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-[2rem] p-6 md:p-8 transition-all duration-500 shadow-sm ${getThemeClasses()} ${
                            isCurrentAyah ? 'border-emerald-500 ring-4 ring-emerald-500/10 scale-[1.01] shadow-2xl z-10' : ''
                        }`}
                    >
                        <div className="absolute -top-4 -left-4 w-10 h-10 rounded-full bg-emerald-600 text-white flex items-center justify-center text-xs font-bold shadow-lg border-4 border-paper">
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-600 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-600/60 font-bold uppercase tracking-widest text-xs">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-800 dark:text-emerald-400' : ''
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Tafseer (Maududi) - High-contrast fix for mobile visibility during recitation */}
                        {settings.showTafseer && tafseerAyah && (
                             <div 
                                className={`text-right transition-all duration-500 rounded-2xl p-4 md:p-6 ${
                                    isCurrentAyah 
                                        ? 'bg-emerald-50/80 dark:bg-emerald-950/40 border-r-4 border-emerald-500 shadow-inner' 
                                        : ''
                                }`} 
                                dir="rtl"
                             >
                                <p 
                                    className={`font-urdu transition-colors duration-300 ${
                                        isCurrentAyah 
                                            ? 'text-black dark:text-white font-bold' 
                                            : 'text-gray-800 dark:text-gray-200'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-widest mb-2 block">English (Saheeh Intl.)</span>
                                <p className="text-lg text-gray-700 dark:text-gray-300 font-sans leading-relaxed">
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);

  // Surah Intro State
  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  // Performance Optimization: Lazy Loading Ayahs
  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Audio state
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  // Intersection Observer for Infinite Scroll
  useEffect(() => {
    if (!data || loading) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => {
      if (loadMoreRef.current) observer.unobserve(loadMoreRef.current);
    };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);

        if (isMounted) {
          setData(result);

          if (initialAyah) {
            setShowIntro(false); 
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }

          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => {
                if (isMounted) setSurahIntro(text);
              })
              .finally(() => {
                if (isMounted) setLoadingIntro(false);
              });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];

      if (currentAyahIndex >= visibleCount) {
          setVisibleCount(prev => prev + 20);
      }

      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => {
            console.error("Audio play failed", e);
            handleAyahEnd();
          });
        } else {
            handleAyahEnd();
        }
      };

      playArabic();

      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) {
            element.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-gray-100';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-[#5b4636]';
      default: return 'bg-white border-emerald-50 text-gray-900';
    }
  };

  const getFontClasses = () => {
    const isIndoPak = settings.script === 'indopak';
    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerStyle = () => {
    switch(settings.tafseerFontSize) {
      case 'sm': return { fontSize: '1.4rem', lineHeight: '3.0rem' }; 
      case 'base': return { fontSize: '1.6rem', lineHeight: '3.4rem' };
      case 'lg': return { fontSize: '2.0rem', lineHeight: '4.2rem' }; 
      case 'xl': return { fontSize: '2.4rem', lineHeight: '5.0rem' };
      case '2xl': return { fontSize: '3.0rem', lineHeight: '6.2rem' };
      default: return { fontSize: '2.0rem', lineHeight: '4.2rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Panel omitted for brevity, same as previous */}

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors dark:hover:bg-gray-800">
                    <X size={24} />
                </button>
            </div>
            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                {/* Theme, Font size, Urdu Size, Script settings same as previous but kept for functionality */}
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button key={t} onClick={() => onUpdateSettings({...settings, theme: t})} className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'} ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}>
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button key={f} onClick={() => onUpdateSettings({...settings, fontSize: f})} className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'}`}>
                                <Type size={18} />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2">
                    <ArrowLeft size={24} />
                </button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                 <button onClick={() => setShowChat(true)} className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"><Sparkles size={20} /></button>
                 <button onClick={() => setShowSettings(true)} className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"><SettingsIcon size={20} /></button>
                 <div className="flex items-center space-x-2 bg-emerald-900 p-1.5 rounded-full shadow-lg">
                    <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"><SkipBack size={18} fill="currentColor" /></button>
                    <button onClick={() => { if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); } else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); } }} className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-900 shadow-sm">{isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}</button>
                    <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"><SkipForward size={18} fill="currentColor" /></button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-4xl mx-auto px-2 md:px-6 py-12">
        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];
                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-[2rem] p-6 md:p-8 transition-all duration-500 shadow-sm ${getThemeClasses()} ${
                            isCurrentAyah ? 'border-emerald-700 ring-8 ring-emerald-500/5 scale-[1.01] shadow-2xl z-10' : ''
                        }`}
                    >
                        <div className={`absolute -top-4 -left-4 w-10 h-10 rounded-full flex items-center justify-center text-xs font-black shadow-lg border-4 transition-colors ${
                            isCurrentAyah ? 'bg-gold-500 text-white border-gold-100' : 'bg-emerald-800 text-white border-paper'
                        }`}>
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-800 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-800/40 font-bold uppercase tracking-widest text-[10px]">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text - Refined Coloring */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify ${getFontClasses()} ${
                                isCurrentAyah ? 'text-emerald-950 dark:text-emerald-400 font-bold' : 'text-gray-900 dark:text-gray-100'
                            }`}>
                                {ayah.text} <span className="text-gold-500 mx-2 select-none opacity-50">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gradient-to-l from-transparent via-emerald-200/50 to-transparent mb-8"></div>

                        {/* Urdu Translation - FIXED: Pure Black, No Grey backgrounds */}
                        {settings.showTafseer && tafseerAyah && (
                             <div 
                                className={`text-right transition-all duration-500 rounded-2xl p-4 md:p-6 border-r-4 ${
                                    isCurrentAyah 
                                        ? 'border-gold-500 shadow-sm' 
                                        : 'border-transparent'
                                }`} 
                                dir="rtl"
                             >
                                <p 
                                    className={`font-urdu transition-colors duration-300 leading-loose ${
                                        isCurrentAyah 
                                            ? 'text-black dark:text-white' 
                                            : 'text-gray-950 dark:text-gray-100'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-[10px] font-black text-emerald-800/40 uppercase tracking-widest mb-2 block">English Translation</span>
                                <p className={`text-lg font-sans leading-relaxed ${isCurrentAyah ? 'text-black dark:text-white' : 'text-gray-700 dark:text-gray-300'}`}>
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-800" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  CheckCircle, Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  WifiOff, Settings as SettingsIcon, X, Moon, Sun, Type,
  Languages, BookOpen, Info, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType, ScriptStyle } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);

  const [surahIntro, setSurahIntro] = useState<string>("");
  const [loadingIntro, setLoadingIntro] = useState(false);
  const [showIntro, setShowIntro] = useState(true);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);

  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '200px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setLoadingIntro(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setSurahIntro("");
      setShowIntro(true);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setShowIntro(false); 
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    const headerHeight = headerRef.current?.offsetHeight || 80;
                    window.scrollTo({ top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 20, behavior: 'smooth' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
          if (navigator.onLine) {
            fetchSurahIntroduction(result.surahInfo.name, surahNumber)
              .then(text => { if (isMounted) setSurahIntro(text); })
              .finally(() => { if (isMounted) setLoadingIntro(false); });
          } else {
            setLoadingIntro(false);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];
      if (currentAyahIndex >= visibleCount) setVisibleCount(prev => prev + 20);
      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(e => { handleAyahEnd(); });
        } else { handleAyahEnd(); }
      };
      playArabic();
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    const isIndoPak = settings.script === 'indopak';
    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' }; // Ensuring thick font
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '3.0rem' }; 
      case 'base': return { ...base, fontSize: '1.6rem', lineHeight: '3.4rem' };
      case 'lg': return { ...base, fontSize: '2.0rem', lineHeight: '4.2rem' }; 
      case 'xl': return { ...base, fontSize: '2.4rem', lineHeight: '5.0rem' };
      case '2xl': return { ...base, fontSize: '3.0rem', lineHeight: '6.2rem' };
      default: return { ...base, fontSize: '2.0rem', lineHeight: '4.2rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Panel */}
      <div className={`fixed inset-0 z-50 transition-opacity duration-300 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-80 md:w-96 shadow-2xl transform transition-transform duration-500 p-6 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'}`}>
            <div className="flex items-center justify-between mb-8 border-b pb-4">
                <h2 className="text-xl font-bold flex items-center">
                    <SettingsIcon className="mr-2" size={20} /> ترتیبات (Settings)
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-2 hover:bg-gray-100 rounded-full dark:hover:bg-gray-800"><X size={24} /></button>
            </div>
            <div className="space-y-8 flex-1 overflow-y-auto pr-2">
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button key={t} onClick={() => onUpdateSettings({...settings, theme: t})} className={`h-12 rounded-lg border-2 flex items-center justify-center transition-all ${settings.theme === t ? 'border-emerald-500 ring-2 ring-emerald-500/20' : 'border-gray-200 dark:border-gray-700'} ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-800'}`}>
                                {t === 'dark' ? <Moon size={18} /> : t === 'sepia' ? <Sun size={18} className="text-amber-600" /> : <Sun size={18} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-600 mb-4">عربی سائز (Arabic Size)</h3>
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-800 p-2 rounded-xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button key={f} onClick={() => onUpdateSettings({...settings, fontSize: f})} className={`w-10 h-10 rounded-lg flex items-center justify-center text-lg transition-all ${settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-gray-200 dark:hover:bg-gray-700'}`}><Type size={18} /></button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-30 backdrop-blur-md border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-paper/95 border-emerald-100'
      } shadow-sm`}>
        <div className="w-full px-2 md:px-6 py-3 flex items-center justify-between">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 text-emerald-600 hover:bg-emerald-100 rounded-full transition-colors mr-2"><ArrowLeft size={24} /></button>
                <div className="hidden md:block">
                  <h1 className="text-xl font-arabic font-bold text-emerald-700">{data?.surahInfo.name}</h1>
                </div>
            </div>

            <div className="flex items-center space-x-2">
                 <button onClick={() => setShowChat(true)} className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"><Sparkles size={20} /></button>
                 <button onClick={() => setShowSettings(true)} className="p-2.5 rounded-full bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors border border-emerald-100 shadow-sm"><SettingsIcon size={20} /></button>
                 <div className="flex items-center space-x-2 bg-emerald-950 p-1.5 rounded-full shadow-lg">
                    <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"><SkipBack size={18} fill="currentColor" /></button>
                    <button onClick={() => { if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); } else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); } }} className="w-9 h-9 flex items-center justify-center rounded-full bg-white text-emerald-900 shadow-sm">{isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-0.5" />}</button>
                    <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-1.5 text-white/70 hover:text-white disabled:opacity-30"><SkipForward size={18} fill="currentColor" /></button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-4xl mx-auto px-2 md:px-6 py-12">
        <div className="flex justify-center mb-12 opacity-80 filter contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-64 md:w-80 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];
                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-[2rem] p-6 md:p-8 transition-all duration-300 shadow-sm ${getThemeClasses()} ${
                            isCurrentAyah ? 'border-emerald-600 border-l-[10px] ring-2 ring-emerald-50 scale-[1.01] shadow-2xl z-10' : ''
                        }`}
                    >
                        <div className={`absolute -top-4 -left-4 w-10 h-10 rounded-full flex items-center justify-center text-xs font-black shadow-lg border-4 transition-colors ${
                            isCurrentAyah ? 'bg-gold-500 text-white border-white' : 'bg-emerald-800 text-white border-white'
                        }`}>
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-8">
                            <div className="flex space-x-1">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-2.5 rounded-full transition-all ${bookmarked ? 'bg-gold-500 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-2.5 rounded-full transition-all ${isCurrentAyah ? 'bg-emerald-950 text-white' : 'hover:bg-emerald-100 text-gray-300 hover:text-emerald-600'}`}>
                                    <Volume2 size={20} />
                                </button>
                            </div>
                            <div className="font-arabic text-emerald-800/40 font-bold uppercase tracking-widest text-[10px]">Ayah {ayah.numberInSurah}</div>
                        </div>

                        {/* Arabic Text - THICK BLACK */}
                        <div className="text-right mb-10" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.8] text-justify font-bold ${getFontClasses()} ${
                                settings.theme === 'dark' ? 'text-white' : 'text-black'
                            }`}>
                                {ayah.text} <span className="text-gold-600 mx-2 select-none">۝</span>
                            </p>
                        </div>

                        <div className="h-px bg-gray-200 dark:bg-gray-700 mb-8"></div>

                        {/* Urdu Translation - THICK BLACK, NO GREY BG */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right py-4" dir="rtl">
                                <p 
                                    className={`font-urdu transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-white' : 'text-black'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {/* English Translation */}
                        {settings.showEnglish && englishAyah && (
                            <div className="mt-8 pt-6 border-t border-dashed border-gray-200 dark:border-gray-700 text-left" dir="ltr">
                                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">English Translation</span>
                                <p className={`text-lg font-sans leading-relaxed font-bold ${settings.theme === 'dark' ? 'text-gray-200' : 'text-gray-900'}`}>
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-20 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-800" size={32} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default Reader;

import React, { useState, useEffect } from 'react';
import { Search, Book, Bookmark as BookmarkIcon, Clock, Trash2, Info, CheckCircle2, WifiOff, Sparkles, Download, CloudDownload, X, AlertCircle, User, Mail, Phone, ArrowDown, Crown, Star } from 'lucide-react';
import { Surah, Bookmark, AppSettings } from '../types';
import { getSurahList, downloadQuranData } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface SurahListProps {
  onSelectSurah: (surahNumber: number, ayahNumber?: number) => void;
  onGoToAbout: () => void;
  settings: AppSettings;
}

const SurahList: React.FC<SurahListProps> = ({ onSelectSurah, onGoToAbout, settings }) => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [filteredSurahs, setFilteredSurahs] = useState<Surah[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showChat, setShowChat] = useState(false);

  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState(0);
  const [showDownloadModal, setShowDownloadModal] = useState(false);
  const [downloadCompleted, setDownloadCompleted] = useState(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const list = await getSurahList();
        setSurahs(list);
        setFilteredSurahs(list);

        const saved = localStorage.getItem('quran_bookmarks');
        if (saved) setBookmarks(JSON.parse(saved));
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const lowerSearch = search.toLowerCase();
    const filtered = surahs.filter(
      (s) =>
        s.englishName.toLowerCase().includes(lowerSearch) ||
        s.englishNameTranslation.toLowerCase().includes(lowerSearch) ||
        s.number.toString().includes(lowerSearch)
    );
    setFilteredSurahs(filtered);
  }, [search, surahs]);

  const deleteBookmark = (e: React.MouseEvent, ts: number) => {
    e.stopPropagation();
    const updated = bookmarks.filter(b => b.timestamp !== ts);
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const handleDownload = async () => {
    if (!isOnline) return;
    setIsDownloading(true);
    setDownloadProgress(0);
    setDownloadCompleted(false);

    try {
      await downloadQuranData(settings.script, (progress) => {
        setDownloadProgress(progress);
      });
      setDownloadCompleted(true);
    } catch (error) {
      console.error("Download failed", error);
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="min-h-screen bg-paper flex flex-col">
      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Browsing Offline
        </div>
      )}

      {/* Hero Section */}
      <div className="bg-emerald-900 text-white pt-6 pb-20 px-6 relative overflow-hidden flex-shrink-0">
        <div className="absolute top-0 right-0 w-[400px] h-[400px] bg-emerald-800 rounded-full mix-blend-multiply filter blur-3xl opacity-20 -translate-y-1/2 translate-x-1/2"></div>

        <div className="max-w-5xl mx-auto relative z-10">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-2">
                 <button onClick={() => setShowChat(true)} className="flex items-center gap-1.5 bg-emerald-800/40 text-emerald-100 hover:text-white hover:bg-emerald-700/50 px-4 py-2 rounded-2xl transition-all text-xs font-bold border border-emerald-700/50 shadow-sm active-press">
                    <Sparkles size={14} className="text-gold-400" />
                    <span>AI Assistant</span>
                </button>
                <button onClick={() => setShowDownloadModal(true)} className="flex items-center gap-1.5 bg-emerald-800/40 text-emerald-100 hover:text-white hover:bg-emerald-700/50 px-4 py-2 rounded-2xl transition-all text-xs font-bold border border-emerald-700/50 shadow-sm active-press">
                    <CloudDownload size={14} />
                    <span>Offline</span>
                </button>
            </div>

            <button onClick={onGoToAbout} className="p-2.5 text-emerald-300 hover:text-white transition-colors bg-emerald-800/40 rounded-2xl border border-emerald-700/50 active-press">
              <Info size={20} />
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-center">
            <div className="text-center lg:text-right">
              <h1 className="font-arabic text-5xl md:text-6xl mb-2 text-gold-400 drop-shadow-2xl">القرآن الكريم</h1>
              <p className="text-emerald-100 text-sm md:text-base font-medium tracking-widest uppercase opacity-80 mb-6">The Holy Quran Urdu Translation</p>

              <div className="relative max-w-md mx-auto lg:mr-0">
                <input
                  type="text"
                  placeholder="Search Surah..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full py-4 px-6 pr-14 rounded-2xl bg-emerald-950/60 backdrop-blur-xl border border-emerald-700/30 text-white placeholder-emerald-400/50 focus:outline-none focus:ring-2 focus:ring-gold-500 shadow-xl transition-all"
                />
                <Search className="absolute right-5 top-1/2 transform -translate-y-1/2 text-emerald-500" size={20} />
              </div>
            </div>

            {/* MONETIZATION STRATEGY: Ad-Free Promotion Section */}
            <div className="bg-gradient-to-br from-gold-600 to-amber-700 rounded-[2rem] p-6 shadow-2xl relative overflow-hidden group border border-white/20">
               <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
                  <Crown size={80} className="text-white" />
               </div>
               <div className="relative z-10">
                  <div className="flex items-center gap-2 text-white/90 mb-2">
                     <Star size={14} fill="currentColor" />
                     <span className="text-[10px] font-black uppercase tracking-widest">Support the Mission</span>
                  </div>
                  <h3 className="text-xl font-black text-white mb-2">Upgrade to Premium</h3>
                  <p className="text-emerald-50 text-xs mb-4 leading-relaxed max-w-[240px]">
                     Remove all advertisements and support the development of Islamic digital tools for everyone.
                  </p>
                  <button className="bg-white text-amber-800 px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg hover:shadow-xl active-press transition-all flex items-center gap-2">
                     <Crown size={14} />
                     Go Ad-Free
                  </button>
               </div>
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 max-w-7xl mx-auto w-full px-4 -mt-10 relative z-20 pb-10 overflow-hidden flex flex-col">
        {bookmarks.length > 0 && !search && (
            <div className="mb-6 flex-shrink-0">
                <div className="flex items-center gap-3 mb-3 text-emerald-900 px-2">
                    <BookmarkIcon size={20} className="text-gold-500" fill="currentColor" />
                    <h2 className="text-lg font-bold">نشانی (Bookmarks)</h2>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                    {bookmarks.map((b) => (
                        <div key={b.timestamp} onClick={() => onSelectSurah(b.surahNumber, b.ayahNumber)} className="flex-shrink-0 w-48 bg-white border border-gold-200 hover:border-gold-500 rounded-2xl p-4 shadow-md transition-all cursor-pointer group active-press">
                            <div className="flex justify-between items-start mb-2">
                                <span className="text-[9px] font-black bg-gold-50 text-gold-700 px-2 py-0.5 rounded-md uppercase">Verse {b.ayahNumber}</span>
                                <button onClick={(e) => deleteBookmark(e, b.timestamp)} className="p-1 text-gray-300 hover:text-red-500"><Trash2 size={14} /></button>
                            </div>
                            <h3 className="font-bold text-gray-800 text-sm truncate">{b.surahName}</h3>
                        </div>
                    ))}
                </div>
            </div>
        )}

        <div className="flex-1 bg-white/60 backdrop-blur-md rounded-[2.5rem] shadow-2xl border border-white/40 overflow-hidden flex flex-col min-h-0">
            <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white/80 backdrop-blur-md z-10">
                <div className="flex items-center gap-3 text-emerald-900">
                    <Book size={24} className="text-emerald-600" />
                    <h2 className="text-xl font-bold">فہرستِ سورت (Surah Index)</h2>
                </div>
                <div className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em]">
                    {filteredSurahs.length} Chapters
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                {loading ? (
                  <LoadingSpinner />
                ) : filteredSurahs.length > 0 ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {filteredSurahs.map((surah) => (
                      <div 
                        key={surah.number} 
                        onClick={() => onSelectSurah(surah.number)} 
                        className="bg-white hover:bg-emerald-50 border border-gray-100 hover:border-emerald-200 rounded-2xl p-4 shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer group flex items-center justify-between min-h-[80px] active-press"
                      >
                        <div className="flex items-center gap-4 min-w-0">
                          <div className="w-10 h-10 relative flex items-center justify-center flex-shrink-0">
                             <div className="absolute inset-0 bg-emerald-100/50 rounded-xl transform rotate-45 group-hover:rotate-90 group-hover:bg-emerald-200 transition-all duration-500"></div>
                             <span className="relative font-black text-emerald-900 text-xs">{surah.number}</span>
                          </div>
                          <div className="min-w-0">
                            <h3 className="font-bold text-gray-800 group-hover:text-emerald-900 text-sm truncate transition-colors">
                                {surah.englishName}
                            </h3>
                            <p className="text-[9px] text-gray-400 uppercase font-bold tracking-tighter truncate opacity-70 group-hover:opacity-100 transition-opacity">
                                {surah.englishNameTranslation}
                            </p>
                          </div>
                        </div>
                        <div className="text-right flex-shrink-0 pl-2">
                            <h3 className="font-arabic text-lg text-emerald-800 mb-0.5 group-hover:scale-110 transition-transform origin-right">{surah.name}</h3>
                            <p className="text-[8px] font-black text-emerald-600/60 uppercase tracking-widest">{surah.numberOfAyahs} Verses</p>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400">
                    <Search size={48} className="mb-4 opacity-20" />
                    <p className="text-lg font-medium">No results found for "{search}"</p>
                  </div>
                )}
            </div>
        </div>
      </div>

      {showDownloadModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-emerald-950/80 backdrop-blur-md" onClick={() => !isDownloading && setShowDownloadModal(false)}></div>
            <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md relative z-10 overflow-hidden border border-white">
                <div className="bg-emerald-600 p-8 text-white relative">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/20 rounded-full -translate-y-1/2 translate-x-1/2"></div>
                    <div className="flex justify-between items-center relative z-10">
                        <h3 className="text-2xl font-bold flex items-center">
                            <Download size={28} className="mr-3" /> Offline Sync
                        </h3>
                        {!isDownloading && (
                            <button onClick={() => setShowDownloadModal(false)} className="hover:bg-black/10 p-2 rounded-2xl transition-all">
                                <X size={24} />
                            </button>
                        )}
                    </div>
                </div>

                <div className="p-10">
                    {downloadCompleted ? (
                        <div className="text-center">
                            <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-6 text-emerald-600 shadow-inner">
                                <CheckCircle2 size={40} />
                            </div>
                            <h4 className="text-2xl font-bold text-gray-800 mb-2">Sync Complete</h4>
                            <p className="text-gray-500 text-sm mb-8">Quran text and Urdu translations are now stored locally.</p>
                            <button onClick={() => setShowDownloadModal(false)} className="bg-emerald-600 text-white px-8 py-4 rounded-2xl font-bold hover:bg-emerald-700 transition-all w-full shadow-lg active-press">
                                Done
                            </button>
                        </div>
                    ) : isDownloading ? (
                        <div className="text-center">
                            <div className="w-full bg-gray-100 rounded-full h-3 mb-6 overflow-hidden border border-gray-100">
                                <div className="bg-emerald-600 h-full transition-all duration-300" style={{ width: `${downloadProgress}%` }}></div>
                            </div>
                            <h4 className="text-3xl font-black text-emerald-700 mb-2">{downloadProgress}%</h4>
                            <p className="text-sm font-bold text-gray-400 uppercase tracking-widest">Caching Holy Verses...</p>
                        </div>
                    ) : (
                        <div className="text-center">
                            <div className="p-6 bg-emerald-50 rounded-3xl mb-8 border border-emerald-100 text-emerald-900 text-sm font-medium leading-relaxed">
                                This will store all 114 Surahs (Text, Urdu Translation, and Tafseer) on your device (~25MB).
                            </div>
                            <button 
                                onClick={handleDownload}
                                disabled={!isOnline}
                                className="bg-emerald-600 text-white px-8 py-4 rounded-2xl font-bold hover:bg-emerald-700 transition-all w-full flex items-center justify-center shadow-lg disabled:opacity-50 active-press"
                            >
                                <CloudDownload size={24} className="mr-3" />
                                {isOnline ? 'Download Now' : 'Connect to Internet'}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
      )}

      <style dangerouslySetInnerHTML={{ __html: `
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #d1fae5; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #10b981; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
