import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  Settings as SettingsIcon, X, Moon, Sun, Type, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '400px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      const ayah = data.arabicAyahs[currentAyahIndex];
      if (currentAyahIndex >= visibleCount) setVisibleCount(prev => prev + 20);
      const playArabic = () => {
         if (audioRef.current && ayah.audio) {
          audioRef.current.src = ayah.audio;
          audioRef.current.play().catch(() => { handleAyahEnd(); });
        } else { handleAyahEnd(); }
      };
      playArabic();
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data]);

  const handleAyahEnd = () => {
    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    const isIndoPak = settings.script === 'indopak';
    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' };
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '2.4rem' }; 
      case 'base': return { ...base, fontSize: '1.6rem', lineHeight: '2.8rem' };
      case 'lg': return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' }; 
      case 'xl': return { ...base, fontSize: '2.3rem', lineHeight: '4.0rem' };
      case '2xl': return { ...base, fontSize: '2.8rem', lineHeight: '4.8rem' };
      default: return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Drawer - Better for Mobile */}
      <div className={`fixed inset-0 z-[100] transition-all duration-500 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute top-0 right-0 h-full w-[85%] md:w-96 shadow-2xl transform transition-transform duration-500 p-8 flex flex-col ${
            showSettings ? 'translate-x-0' : 'translate-x-full'
        } ${settings.theme === 'dark' ? 'bg-gray-950 text-white' : 'bg-white text-gray-950'}`}>
            <div className="flex items-center justify-between mb-10 pb-4 border-b">
                <h2 className="text-2xl font-black flex items-center gap-3">
                    <SettingsIcon className="text-emerald-600" size={24} /> ترتیبات
                </h2>
                <button onClick={() => setShowSettings(false)} className="p-3 bg-gray-100 dark:bg-gray-800 rounded-2xl active-press"><X size={24} /></button>
            </div>
            <div className="space-y-10 overflow-y-auto pr-2 custom-scrollbar">
                <div>
                    <h3 className="text-[10px] font-black uppercase tracking-widest text-emerald-600 mb-5">تھیم (Theme)</h3>
                    <div className="grid grid-cols-3 gap-3">
                        {(['paper', 'sepia', 'dark'] as ThemeType[]).map((t) => (
                            <button key={t} onClick={() => onUpdateSettings({...settings, theme: t})} className={`h-14 rounded-2xl border-2 flex items-center justify-center transition-all active-press ${settings.theme === t ? 'border-emerald-600 bg-emerald-50 dark:bg-emerald-900/20' : 'border-gray-100 dark:border-gray-800'} ${t === 'paper' ? 'bg-white' : t === 'sepia' ? 'bg-[#fdf6e3]' : 'bg-gray-900'}`}>
                                {t === 'dark' ? <Moon size={20} /> : t === 'sepia' ? <Sun size={20} className="text-amber-600" /> : <Sun size={20} className="text-emerald-600" />}
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-[10px] font-black uppercase tracking-widest text-emerald-600 mb-5">عربی سائز (Arabic Size)</h3>
                    <div className="grid grid-cols-5 gap-2 bg-gray-50 dark:bg-gray-900 p-2 rounded-2xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button key={f} onClick={() => onUpdateSettings({...settings, fontSize: f})} className={`h-12 rounded-xl flex items-center justify-center text-sm font-bold transition-all active-press ${settings.fontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>{f.toUpperCase()}</button>
                        ))}
                    </div>
                </div>
                <div>
                    <h3 className="text-[10px] font-black uppercase tracking-widest text-emerald-600 mb-5">اردو سائز (Urdu Size)</h3>
                    <div className="grid grid-cols-5 gap-2 bg-gray-50 dark:bg-gray-900 p-2 rounded-2xl">
                        {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map((f) => (
                            <button key={f} onClick={() => onUpdateSettings({...settings, tafseerFontSize: f})} className={`h-12 rounded-xl flex items-center justify-center text-sm font-bold transition-all active-press ${settings.tafseerFontSize === f ? 'bg-emerald-600 text-white shadow-lg' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}`}>{f.toUpperCase()}</button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
      </div>

       {/* Mobile-Friendly Sticky Header */}
      <div ref={headerRef} className={`sticky top-0 z-40 backdrop-blur-xl border-b transition-colors duration-300 ${
        settings.theme === 'dark' ? 'bg-gray-950/90 border-gray-800' : 
        settings.theme === 'sepia' ? 'bg-[#f4ecd8]/90 border-[#eee8d5]' : 'bg-white/95 border-emerald-100'
      } shadow-md`}>
        <div className="w-full px-4 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <button onClick={onBack} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><ArrowLeft size={24} /></button>
                <h1 className="text-xl font-arabic font-bold text-emerald-800 truncate max-w-[120px] sm:max-w-none">{data?.surahInfo.name}</h1>
            </div>

            <div className="flex items-center gap-3">
                 <button onClick={() => setShowChat(true)} className="p-3 rounded-2xl bg-emerald-50 text-emerald-700 border border-emerald-100 active-press"><Sparkles size={20} /></button>
                 <button onClick={() => setShowSettings(true)} className="p-3 rounded-2xl bg-emerald-50 text-emerald-700 border border-emerald-100 active-press"><SettingsIcon size={20} /></button>

                 <div className="flex items-center gap-1 bg-emerald-950 p-1 rounded-[1.2rem] shadow-xl">
                    <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-2 text-white/50 hover:text-white disabled:opacity-20 active-press"><SkipBack size={18} fill="currentColor" /></button>
                    <button onClick={() => { if (isPlaying) { setIsPlaying(false); setCurrentAyahIndex(-1); } else { setIsPlaying(true); setCurrentAyahIndex(currentAyahIndex === -1 ? 0 : currentAyahIndex); } }} className="w-10 h-10 flex items-center justify-center rounded-2xl bg-white text-emerald-950 shadow-inner active-press transition-all">{isPlaying ? <Pause size={22} fill="currentColor" /> : <Play size={22} fill="currentColor" className="ml-0.5" />}</button>
                    <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-2 text-white/50 hover:text-white disabled:opacity-20 active-press"><SkipForward size={18} fill="currentColor" /></button>
                </div>
            </div>
        </div>
      </div>

      <div className="w-full max-w-4xl mx-auto px-4 py-12">
        <div className="flex justify-center mb-16 opacity-90 contrast-125">
            <img src="https://upload.wikimedia.org/wikipedia/commons/2/27/Basmala.svg" alt="Bismillah" className={`w-72 md:w-96 h-auto ${settings.theme === 'dark' ? 'invert' : ''}`} />
        </div>

        <div className="space-y-10">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, index) => {
                const englishAyah = data.englishAyahs?.[index];
                const tafseerAyah = data.tafseerAyahs?.[index];
                const isCurrentAyah = currentAyahIndex === index;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative border rounded-[2.5rem] p-8 md:p-10 transition-all duration-300 shadow-xl ${getThemeClasses()} ${
                            isCurrentAyah ? 'border-emerald-600 border-l-[12px] ring-4 ring-emerald-500/5 scale-[1.02] z-10' : ''
                        }`}
                    >
                        <div className={`absolute -top-4 -right-4 w-12 h-12 rounded-2xl flex items-center justify-center text-xs font-black shadow-xl border-4 transition-colors ${
                            isCurrentAyah ? 'bg-gold-500 text-white border-white' : 'bg-emerald-900 text-white border-white'
                        }`}>
                            {ayah.numberInSurah}
                        </div>

                        <div className="flex justify-between items-start mb-10">
                            <div className="flex gap-2">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-3 rounded-2xl transition-all active-press ${bookmarked ? 'bg-gold-500 text-white' : 'bg-gray-50 text-gray-300 hover:text-emerald-700 dark:bg-gray-800'}`}>
                                    {bookmarked ? <BookmarkCheck size={22} /> : <BookmarkIcon size={22} />}
                                </button>
                                <button onClick={() => setCurrentAyahIndex(index)} className={`p-3 rounded-2xl transition-all active-press ${isCurrentAyah ? 'bg-emerald-950 text-white' : 'bg-gray-50 text-gray-300 hover:text-emerald-700 dark:bg-gray-800'}`}>
                                    <Volume2 size={22} />
                                </button>
                            </div>
                        </div>

                        {/* Arabic Text - THICK BLACK AS REQUESTED */}
                        <div className="text-right mb-12" dir="rtl">
                            <p className={`${settings.script === 'indopak' ? 'font-indopak' : 'font-arabic'} leading-[2.6] text-justify font-bold ${getFontClasses()} ${
                                settings.theme === 'dark' ? 'text-white' : 'text-black'
                            }`}>
                                {ayah.text} <span className="text-gold-600 mx-2 select-none opacity-60">۝</span>
                            </p>
                        </div>

                        <div className="h-0.5 bg-gray-100 dark:bg-gray-800 mb-10 rounded-full"></div>

                        {/* Urdu Translation - THICK BLACK, NO GREY HIGHLIGHTS */}
                        {settings.showTafseer && tafseerAyah && (
                             <div className="text-right" dir="rtl">
                                <p 
                                    className={`font-urdu font-bold transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-white' : 'text-black'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}

                        {settings.showEnglish && englishAyah && (
                            <div className="mt-10 pt-8 border-t border-dashed border-gray-100 dark:border-gray-800 text-left" dir="ltr">
                                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 block">Translation</span>
                                <p className={`text-lg font-sans leading-relaxed font-bold ${settings.theme === 'dark' ? 'text-gray-200' : 'text-gray-950'}`}>
                                    {englishAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-32 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-800" size={40} />
              </div>
            )}
        </div>
      </div>
      <AIChat context={`Reading Surah ${data?.surahInfo.englishName}`} isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  Settings as SettingsIcon, X, Moon, Sun, Type, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType } from '../types';
import { getSurahDetails } from '../services/quranApi';
import { fetchSurahIntroduction } from '../services/geminiService';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

const BISMILLAH_TEXT = "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ";
const BISMILLAH_AUDIO = "https://cdn.islamic.network/quran/audio/128/ar.alafasy/1.mp3";

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isBismillahPlaying, setIsBismillahPlaying] = useState(false);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hasPlayedBismillahRef = useRef<boolean>(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '400px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsBismillahPlaying(false);
      hasPlayedBismillahRef.current = false;

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const playAyah = useCallback((index: number) => {
    if (!data) return;

    // Logic for Bismillah: Play only at the start of index 0 for Surahs other than 1 and 9
    if (index === 0 && surahNumber !== 9 && surahNumber !== 1 && !hasPlayedBismillahRef.current) {
        setIsBismillahPlaying(true);
        if (audioRef.current) {
            audioRef.current.src = BISMILLAH_AUDIO;
            audioRef.current.play().catch(() => {
                setIsBismillahPlaying(false);
                hasPlayedBismillahRef.current = true;
                playAyah(0);
            });
        }
        return;
    }

    const ayah = data.arabicAyahs[index];
    if (index >= visibleCount) setVisibleCount(prev => prev + 20);

    if (audioRef.current && ayah.audio) {
      audioRef.current.src = ayah.audio;
      audioRef.current.play().catch(() => { handleAyahEnd(); });
    } else { 
      handleAyahEnd(); 
    }
  }, [data, surahNumber, visibleCount]);

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      playAyah(currentAyahIndex);
      const ayah = data.arabicAyahs[currentAyahIndex];
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data, playAyah]);

  const handleAyahEnd = () => {
    if (isBismillahPlaying) {
        setIsBismillahPlaying(false);
        hasPlayedBismillahRef.current = true;
        playAyah(0);
        return;
    }

    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    const isIndoPak = settings.script === 'indopak';
    switch(settings.fontSize) {
      case 'sm': return isIndoPak ? 'text-2xl md:text-3xl' : 'text-xl md:text-2xl';
      case 'lg': return isIndoPak ? 'text-4xl md:text-5xl' : 'text-3xl md:text-4xl';
      case 'xl': return isIndoPak ? 'text-5xl md:text-6xl' : 'text-4xl md:text-5xl';
      case '2xl': return isIndoPak ? 'text-6xl md:text-7xl' : 'text-5xl md:text-6xl';
      default: return isIndoPak ? 'text-3xl md:text-4xl' : 'text-2xl md:text-3xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' };
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '2.4rem' }; 
      case 'base': return { ...base, fontSize: '1.6rem', lineHeight: '2.8rem' };
      case 'lg': return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' }; 
      case 'xl': return { ...base, fontSize: '2.3rem', lineHeight: '4.0rem' };
      case '2xl': return { ...base, fontSize: '2.8rem', lineHeight: '4.8rem' };
      default: return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Drawer */}
      <div className={`fixed inset-0 z-[100] transition-all duration-500 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute bottom-0 left-0 right-0 ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-black'} rounded-t-[2.5rem] p-8 shadow-2xl transition-transform duration-500 transform ${showSettings ? 'translate-y-0' : 'translate-y-full'}`}>
            <div className="max-w-xl mx-auto">
                <div className="flex justify-between items-center mb-8">
                    <h3 className="text-2xl font-black">Settings</h3>
                    <button onClick={() => setShowSettings(false)} className="p-2 bg-black/5 rounded-2xl opacity-60 hover:opacity-100 transition-opacity"><X size={24} /></button>
                </div>

                <div className="space-y-8">
                    <div>
                        <label className="text-xs font-bold uppercase tracking-widest opacity-50 mb-3 block">Theme</label>
                        <div className="flex gap-3">
                            {(['paper', 'sepia', 'dark'] as ThemeType[]).map(t => (
                                <button 
                                    key={t} 
                                    onClick={() => onUpdateSettings({...settings, theme: t})}
                                    className={`flex-1 py-4 rounded-2xl font-bold capitalize border-2 transition-all ${settings.theme === t ? 'border-emerald-600 bg-emerald-50/10 text-emerald-600' : 'border-black/5 text-gray-400'}`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div>
                        <label className="text-xs font-bold uppercase tracking-widest opacity-50 mb-3 block">Font Size</label>
                        <div className="flex gap-2">
                            {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map(size => (
                                <button 
                                    key={size} 
                                    onClick={() => onUpdateSettings({...settings, fontSize: size})}
                                    className={`flex-1 py-3 rounded-xl font-bold uppercase text-xs border-2 transition-all ${settings.fontSize === size ? 'border-emerald-600 bg-emerald-50/10 text-emerald-600' : 'border-black/5 text-gray-400'}`}
                                >
                                    {size}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex items-center justify-between p-4 bg-black/5 rounded-2xl">
                        <div>
                            <p className="font-bold text-sm">Show Urdu Translation</p>
                            <p className="text-[10px] opacity-60 uppercase font-bold tracking-widest">Tafheem-ul-Quran</p>
                        </div>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-12 h-6 rounded-full transition-colors relative ${settings.showTafseer ? 'bg-emerald-600' : 'bg-gray-300'}`}
                        >
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.showTafseer ? 'right-1' : 'left-1'}`}></div>
                        </button>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <header ref={headerRef} className={`sticky top-0 z-50 px-6 py-4 flex items-center justify-between border-b transition-colors ${getThemeClasses()}`}>
        <button onClick={onBack} className="p-2 hover:bg-black/5 rounded-full transition-colors"><ArrowLeft size={24} /></button>
        <div className="text-center">
            <h1 className="font-arabic text-2xl text-emerald-600 leading-none mb-1">{data?.surahInfo.name}</h1>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">{data?.surahInfo.englishName}</p>
        </div>
        <button onClick={() => setShowSettings(true)} className="p-2 hover:bg-black/5 rounded-full transition-colors"><SettingsIcon size={24} /></button>
      </header>

      <main className="max-w-4xl mx-auto px-6 pt-10">
        {surahNumber !== 1 && surahNumber !== 9 && (
            <div className={`text-center mb-16 py-10 border-b border-emerald-100/20 border-dashed font-arabic text-4xl opacity-90 ${settings.theme === 'dark' ? 'text-emerald-400' : 'text-emerald-800'}`}>
                {BISMILLAH_TEXT}
            </div>
        )}

        <div className="space-y-16">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, idx) => (
                <div key={ayah.number} id={`ayah-${ayah.numberInSurah}`} className={`group relative py-8 transition-all duration-500 ${currentAyahIndex === idx ? 'scale-[1.03] -mx-4 px-8 rounded-[2rem] bg-emerald-50/30 ring-1 ring-emerald-100 shadow-xl' : ''}`}>
                    <div className="flex justify-between items-center mb-10">
                        <div className="flex items-center gap-4">
                            <div className={`w-10 h-10 flex items-center justify-center rounded-xl font-black text-xs transition-colors ${currentAyahIndex === idx ? 'bg-emerald-600 text-white' : 'bg-emerald-100 text-emerald-700'}`}>
                                {ayah.numberInSurah}
                            </div>
                            <div className="flex gap-1">
                                <button 
                                    onClick={() => toggleBookmark(ayah.numberInSurah)} 
                                    className={`p-2 rounded-lg transition-all ${bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah) ? 'text-gold-500 bg-gold-50' : 'text-gray-300 hover:text-emerald-600 hover:bg-emerald-50'}`}
                                >
                                    {bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah) ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button 
                                    onClick={() => { setCurrentAyahIndex(idx); setIsPlaying(true); }}
                                    className={`p-2 rounded-lg transition-all ${currentAyahIndex === idx && isPlaying ? 'text-emerald-600 bg-emerald-100 animate-pulse' : 'text-gray-300 hover:text-emerald-600 hover:bg-emerald-50'}`}
                                >
                                    {currentAyahIndex === idx && isPlaying ? <Volume2 size={20} /> : <Play size={20} />}
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className={`font-arabic text-right mb-10 leading-[1.8] tracking-wide transition-all ${getFontClasses()}`} dir="rtl">
                        {ayah.text}
                    </div>

                    {settings.showEnglish && (
                        <div className="text-gray-500 text-sm mb-8 leading-relaxed italic opacity-70 border-l-2 border-gray-100 pl-6">
                            {data.englishAyahs[idx].text}
                        </div>
                    )}

                    {settings.showTafseer && (
                        <div className={`font-urdu text-right border-r-4 border-emerald-500/20 pr-8 transition-all ${settings.theme === 'dark' ? 'text-emerald-100/90' : 'text-emerald-950/90'}`} style={getTafseerStyle()} dir="rtl">
                            {data.tafseerAyahs[idx].text}
                        </div>
                    )}
                </div>
            ))}
        </div>

        <div ref={loadMoreRef} className="h-40 flex items-center justify-center">
            {visibleCount < (data?.arabicAyahs.length || 0) && (
                <div className="flex flex-col items-center gap-3">
                    <Loader2 className="animate-spin text-emerald-600" size={32} />
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400">Loading Verses</span>
                </div>
            )}
        </div>
      </main>

      {/* Action Bars / Floating UI */}
      <div className="fixed bottom-8 right-8 flex flex-col gap-4 z-[60]">
         <button 
            onClick={() => setShowChat(true)}
            className="w-16 h-16 bg-emerald-600 text-white rounded-[1.5rem] shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all group"
         >
            <Sparkles size={28} className="group-hover:rotate-12 transition-transform" />
         </button>
      </div>

      <AIChat 
        isOpen={showChat} 
        onClose={() => setShowChat(false)} 
        context={`The user is reading Surah ${data?.surahInfo.englishName} (${data?.surahInfo.name}). The current Ayah is ${currentAyahIndex + 1}.`} 
      />
    </div>
  );
};

