import { GoogleGenAI } from "@google/genai";

// Always initialize a new GoogleGenAI instance right before making an API call to ensure it uses the latest configuration.

export const askIslamicScholar = async (
  query: string,
  context?: string
): Promise<string> => {
  try {
    // Initializing correctly with a named parameter object.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const systemInstruction = `
You are a knowledgeable, respectful, and gentle Islamic scholar assistant.
Your goal is to help users understand the Quran and Islamic teachings.
You primarily speak in Urdu if the user asks in Urdu, or English if asked in English.
However, since this is a Quran app with Urdu translation, favor Urdu explanations for Tafseer.
Keep answers concise, accurate, and always reference Quranic verses if possible.
Avoid controversial sectarian debates; focus on the consensus (Ijma) or general understanding.

If a context (current Surah/Ayah) is provided, use it to frame your answer.
    `;

    // Complex reasoning tasks use gemini-3-pro-preview.
    const model = 'gemini-3-pro-preview';

    let finalPrompt = query;
    if (context) {
        finalPrompt = `Context: ${context}\n\nUser Question: ${query}`;
    }

    const response = await ai.models.generateContent({
      model: model,
      contents: finalPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.3,
      },
    });

    // Access the text property directly from the response.
    return response.text || "مذرت، میں ابھی جواب دینے سے قاصر ہوں۔"; 
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Something went wrong. Please check your API key or try again later.";
  }
};

export const fetchSurahIntroduction = async (surahName: string, surahNumber: number): Promise<string> => {
  const cacheKey = `surah_intro_${surahNumber}_v1`;
  const cached = localStorage.getItem(cacheKey);
  if (cached) return cached;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      Provide a comprehensive introduction for Surah ${surahName} (Chapter ${surahNumber}) based specifically on the commentary "Tafheem-ul-Quran" by Maulana Abul A'la Maududi.

      Output language: Urdu (اردو).

      Please cover the following points clearly:
      1. Period of Revelation (Is it Makki or Madani? In which year or phase of Prophethood was it revealed?)
      2. Historical Background (Conditions/Asbab al-Nuzul: What was happening in the life of the Holy Prophet (PBUH) and Muslims when this was revealed?)
      3. Central Theme (What is the main subject matter and stories discussed?)

      Format the response in clean Markdown with bold headings in Urdu. Keep the tone scholarly yet accessible.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.3,
      }
    });

    // Access the text property directly.
    const text = response.text || "";
    if (text) {
      localStorage.setItem(cacheKey, text);
    }
    return text;
  } catch (error) {
    console.error("Error fetching surah intro:", error);
    return "";
  }
};

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  Settings as SettingsIcon, X, Moon, Sun, Type, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

const BISMILLAH_TEXT = "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ";
const BISMILLAH_AUDIO = "https://cdn.islamic.network/quran/audio/128/ar.alafasy/1.mp3";

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isBismillahPlaying, setIsBismillahPlaying] = useState(false);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hasPlayedBismillahRef = useRef<boolean>(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '400px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsBismillahPlaying(false);
      hasPlayedBismillahRef.current = false;

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const playAyah = useCallback((index: number) => {
    if (!data) return;

    // Taj Quran Recitation: Start with Bismillah for every surah except 1 and 9
    if (index === 0 && surahNumber !== 9 && surahNumber !== 1 && !hasPlayedBismillahRef.current) {
        setIsBismillahPlaying(true);
        if (audioRef.current) {
            audioRef.current.src = BISMILLAH_AUDIO;
            audioRef.current.play().catch(() => {
                setIsBismillahPlaying(false);
                hasPlayedBismillahRef.current = true;
                playAyah(0);
            });
        }
        return;
    }

    const ayah = data.arabicAyahs[index];
    if (index >= visibleCount) setVisibleCount(prev => prev + 20);

    if (audioRef.current && ayah.audio) {
      audioRef.current.src = ayah.audio;
      audioRef.current.play().catch(() => { handleAyahEnd(); });
    } else { 
      handleAyahEnd(); 
    }
  }, [data, surahNumber, visibleCount]);

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      playAyah(currentAyahIndex);
      const ayah = data.arabicAyahs[currentAyahIndex];
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data, playAyah]);

  const handleAyahEnd = () => {
    if (isBismillahPlaying) {
        setIsBismillahPlaying(false);
        hasPlayedBismillahRef.current = true;
        playAyah(0);
        return;
    }

    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    // Taj Company Style Scaling
    switch(settings.fontSize) {
      case 'sm': return 'text-2xl md:text-3xl';
      case 'lg': return 'text-4xl md:text-5xl';
      case 'xl': return 'text-5xl md:text-6xl';
      case '2xl': return 'text-6xl md:text-7xl';
      default: return 'text-3xl md:text-4xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' };
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '2.4rem' }; 
      case 'base': return { ...base, fontSize: '1.6rem', lineHeight: '2.8rem' };
      case 'lg': return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' }; 
      case 'xl': return { ...base, fontSize: '2.3rem', lineHeight: '4.0rem' };
      case '2xl': return { ...base, fontSize: '2.8rem', lineHeight: '4.8rem' };
      default: return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Drawer */}
      <div className={`fixed inset-0 z-[100] transition-all duration-500 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute bottom-0 left-0 right-0 ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-black'} rounded-t-[2.5rem] p-8 shadow-2xl transition-transform duration-500 transform ${showSettings ? 'translate-y-0' : 'translate-y-full'}`}>
            <div className="max-w-xl mx-auto">
                <div className="flex justify-between items-center mb-8">
                    <h3 className="text-2xl font-black">Settings</h3>
                    <button onClick={() => setShowSettings(false)} className="p-2 bg-black/5 rounded-2xl opacity-60 hover:opacity-100 transition-opacity"><X size={24} /></button>
                </div>
                <div className="space-y-8">
                    <div>
                        <label className="text-xs font-bold uppercase tracking-widest opacity-50 mb-3 block">Theme</label>
                        <div className="flex gap-3">
                            {(['paper', 'sepia', 'dark'] as ThemeType[]).map(t => (
                                <button 
                                    key={t} 
                                    onClick={() => onUpdateSettings({...settings, theme: t})}
                                    className={`flex-1 py-4 rounded-2xl font-bold capitalize border-2 transition-all ${settings.theme === t ? 'border-emerald-600 bg-emerald-50/10 text-emerald-600' : 'border-black/5 text-gray-400'}`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-xs font-bold uppercase tracking-widest opacity-50 mb-3 block">Text Size</label>
                        <div className="flex gap-2">
                            {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map(size => (
                                <button 
                                    key={size} 
                                    onClick={() => onUpdateSettings({...settings, fontSize: size})}
                                    className={`flex-1 py-3 rounded-xl font-bold uppercase text-xs border-2 transition-all ${settings.fontSize === size ? 'border-emerald-600 bg-emerald-50/10 text-emerald-600' : 'border-black/5 text-gray-400'}`}
                                >
                                    {size}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="flex items-center justify-between p-4 bg-black/5 rounded-2xl">
                        <div>
                            <p className="font-bold text-sm">Urdu Translation</p>
                            <p className="text-[10px] opacity-60 uppercase font-bold tracking-widest">Tafheem-ul-Quran</p>
                        </div>
                        <button 
                            onClick={() => onUpdateSettings({...settings, showTafseer: !settings.showTafseer})}
                            className={`w-12 h-6 rounded-full transition-colors relative ${settings.showTafseer ? 'bg-emerald-600' : 'bg-gray-300'}`}
                        >
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.showTafseer ? 'right-1' : 'left-1'}`}></div>
                        </button>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <header ref={headerRef} className={`sticky top-0 z-50 px-6 py-4 flex items-center justify-between border-b transition-colors shadow-sm ${getThemeClasses()}`}>
        <button onClick={onBack} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><ArrowLeft size={24} /></button>
        <div className="text-center">
            <h1 className="font-arabic text-2xl text-emerald-800 leading-none mb-1 font-bold">{data?.surahInfo.name}</h1>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">{data?.surahInfo.englishName}</p>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowChat(true)} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><Sparkles size={22} /></button>
            <button onClick={() => setShowSettings(true)} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><SettingsIcon size={22} /></button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 pt-12">
        {/* Bismillah on a Separate line with Taj Quran Style decoration */}
        {surahNumber !== 1 && surahNumber !== 9 && (
            <div className="flex flex-col items-center mb-16">
                <div className={`text-center py-8 px-12 border-y-2 border-dashed border-emerald-100/40 w-full max-w-md ${settings.theme === 'dark' ? 'text-emerald-400' : 'text-emerald-800'}`}>
                    <p className="font-indopak text-4xl md:text-5xl leading-relaxed text-black dark:text-white" dir="rtl">
                        {BISMILLAH_TEXT}
                    </p>
                </div>
            </div>
        )}

        <div className="space-y-16">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, idx) => {
                const tafseerAyah = data.tafseerAyahs?.[idx];
                const isCurrentAyah = currentAyahIndex === idx;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative py-10 transition-all duration-500 border-b border-gray-100 dark:border-gray-800 last:border-0 ${
                            isCurrentAyah ? 'bg-emerald-50/20 -mx-4 px-4 rounded-[2rem]' : ''
                        }`}
                    >
                        <div className="flex justify-between items-center mb-10">
                            <div className={`w-12 h-12 flex items-center justify-center rounded-2xl font-black text-sm shadow-sm transition-colors ${
                                isCurrentAyah ? 'bg-emerald-600 text-white' : 'bg-emerald-100 text-emerald-800'
                            }`}>
                                {ayah.numberInSurah}
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-3 rounded-2xl transition-all active-press ${bookmarked ? 'bg-gold-500 text-white' : 'bg-gray-100 text-gray-300 hover:text-emerald-700 dark:bg-gray-800'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => { setCurrentAyahIndex(idx); setIsPlaying(true); }} className={`p-3 rounded-2xl transition-all active-press ${isCurrentAyah ? 'bg-emerald-950 text-white' : 'bg-gray-100 text-gray-300 hover:text-emerald-700 dark:bg-gray-800'}`}>
                                    {isCurrentAyah && isPlaying ? <Pause size={20} /> : <Play size={20} />}
                                </button>
                            </div>
                        </div>

                        {/* Taj Quran Thick Black Arabic Text */}
                        <div className="text-right mb-12" dir="rtl">
                            <p className={`font-indopak font-bold text-black dark:text-white ${getFontClasses()}`}>
                                {ayah.text} <span className="text-emerald-600/40 mx-2 select-none opacity-60">۝</span>
                            </p>
                        </div>

                        {/* Urdu Taj-Style Thick Black Text */}
                        {settings.showTafseer && tafseerAyah && (
                            <div className="text-right border-r-4 border-emerald-100/30 pr-8" dir="rtl">
                                <p 
                                    className={`font-urdu font-bold transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-emerald-100/90' : 'text-black'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-40 flex items-center justify-center">
                 <Loader2 className="animate-spin text-emerald-600" size={40} />
              </div>
            )}
        </div>
      </main>

      {/* Floating Control Bar for better mobile UX */}
      {isPlaying && (
          <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-[60] bg-emerald-950 text-white px-6 py-4 rounded-[2rem] shadow-2xl flex items-center gap-6 border border-white/10 backdrop-blur-xl">
             <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-2 opacity-60 hover:opacity-100 active-press"><SkipBack size={20} /></button>
             <button onClick={() => setIsPlaying(!isPlaying)} className="w-12 h-12 flex items-center justify-center bg-white text-emerald-950 rounded-2xl shadow-xl active-press">{isPlaying ? <Pause size={24} /> : <Play size={24} />}</button>
             <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-2 opacity-60 hover:opacity-100 active-press"><SkipForward size={20} /></button>
             <div className="h-8 w-px bg-white/10 mx-2"></div>
             <button onClick={() => { setIsPlaying(false); setCurrentAyahIndex(-1); }} className="p-2 opacity-60 hover:opacity-100 active-press"><X size={20} /></button>
          </div>
      )}

      <AIChat 
        isOpen={showChat} 
        onClose={() => setShowChat(false)} 
        context={`Reading Surah ${data?.surahInfo.englishName}. Currently at Ayah ${currentAyahIndex + 1}.`} 
      />
    </div>
  );
};

