        <div className="text-center">
            <h1 className="font-arabic text-2xl text-emerald-800 leading-none mb-1 font-bold">{data?.surahInfo.name}</h1>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">{data?.surahInfo.englishName}</p>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowChat(true)} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><Sparkles size={22} /></button>
            <button onClick={() => setShowSettings(true)} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><SettingsIcon size={22} /></button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 pt-12">
        {surahNumber !== 1 && surahNumber !== 9 && (
            <div className="flex flex-col items-center mb-16">
                <div className={`text-center py-10 px-12 border-y-4 border-double border-emerald-900/10 w-full max-w-lg ${settings.theme === 'dark' ? 'text-emerald-400' : 'text-black'}`}>
                    <p className="font-indopak text-4xl md:text-5xl leading-relaxed" dir="rtl">
                        {BISMILLAH_TEXT}
                    </p>
                </div>
            </div>
        )}

        <div className="space-y-20">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, idx) => {
                const tafseerAyah = data.tafseerAyahs?.[idx];
                const isCurrentAyah = currentAyahIndex === idx;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative py-12 transition-all duration-500 border-b border-gray-100 dark:border-gray-800 last:border-0 ${
                            isCurrentAyah ? 'bg-emerald-50/30 -mx-6 px-6 rounded-[3rem] ring-1 ring-emerald-100 shadow-xl' : ''
                        }`}
                    >
                        <div className="flex justify-between items-center mb-12">
                            <div className={`w-12 h-12 flex items-center justify-center rounded-2xl font-black text-sm shadow-md transition-colors ${
                                isCurrentAyah ? 'bg-emerald-700 text-white animate-bounce-subtle' : 'bg-emerald-100 text-emerald-900'
                            }`}>
                                {ayah.numberInSurah}
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-3.5 rounded-2xl transition-all active-press shadow-sm ${bookmarked ? 'bg-gold-500 text-white' : 'bg-white text-gray-300 hover:text-emerald-700 dark:bg-gray-800 border border-gray-100 dark:border-gray-700'}`}>
                                    {bookmarked ? <BookmarkCheck size={20} /> : <BookmarkIcon size={20} />}
                                </button>
                                <button onClick={() => { setCurrentAyahIndex(idx); setIsPlaying(true); }} className={`p-3.5 rounded-2xl transition-all active-press shadow-sm ${isCurrentAyah ? 'bg-emerald-900 text-white' : 'bg-white text-gray-300 hover:text-emerald-700 dark:bg-gray-800 border border-gray-100 dark:border-gray-700'}`}>
                                    {isCurrentAyah && isPlaying ? <Pause size={20} /> : <Play size={20} />}
                                </button>
                            </div>
                        </div>

                        <div className="text-right mb-14" dir="rtl">
                            <p className={`font-indopak ${getFontClasses()}`} style={{ whiteSpace: 'normal', overflowWrap: 'break-word' }}>
                                {ayah.text} <span className="text-emerald-900/10 mx-3 select-none">۝</span>
                            </p>
                        </div>

                        {settings.showTafseer && tafseerAyah && (
                            <div className="text-right border-r-8 border-emerald-900/5 pr-10" dir="rtl">
                                <p 
                                    className={`font-urdu transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-emerald-50' : 'text-gray-900'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-60 flex flex-col items-center justify-center gap-4">
                 <Loader2 className="animate-spin text-emerald-700" size={48} />
                 <p className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.3em]">Loading More Verses</p>
              </div>
            )}
        </div>
      </main>

      {isPlaying && (
          <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 z-[60] bg-emerald-950/95 text-white px-8 py-5 rounded-[2.5rem] shadow-2xl flex items-center gap-8 border border-white/20 backdrop-blur-2xl transition-all">
             <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-2.5 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipBack size={24} /></button>
             <button onClick={() => setIsPlaying(!isPlaying)} className="w-14 h-14 flex items-center justify-center bg-gold-500 text-emerald-950 rounded-full shadow-2xl active-press group">
                {isPlaying ? <Pause size={28} className="fill-current" /> : <Play size={28} className="fill-current" />}
             </button>
             <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-2.5 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipForward size={24} /></button>
             <div className="h-10 w-px bg-white/20 mx-2"></div>
             <button onClick={() => { setIsPlaying(false); setCurrentAyahIndex(-1); }} className="p-2.5 opacity-60 hover:text-red-400 hover:opacity-100 active-press"><X size={24} /></button>
          </div>
      )}

      <AIChat 
        isOpen={showChat} 
        onClose={() => setShowChat(false)} 
        context={`Reading Surah ${data?.surahInfo.englishName} in Taj Quran Lahore style. Currently at Ayah ${currentAyahIndex + 1}.`} 
      />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  Settings as SettingsIcon, X, Moon, Sun, Type, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

const BISMILLAH_TEXT = "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ";
const BISMILLAH_AUDIO = "https://cdn.islamic.network/quran/audio/128/ar.alafasy/1.mp3";

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isBismillahPlaying, setIsBismillahPlaying] = useState(false);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hasPlayedBismillahRef = useRef<boolean>(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '400px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsBismillahPlaying(false);
      hasPlayedBismillahRef.current = false;

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const playAyah = useCallback((index: number) => {
    if (!data) return;

    if (index === 0 && surahNumber !== 9 && surahNumber !== 1 && !hasPlayedBismillahRef.current) {
        setIsBismillahPlaying(true);
        if (audioRef.current) {
            audioRef.current.src = BISMILLAH_AUDIO;
            audioRef.current.play().catch(() => {
                setIsBismillahPlaying(false);
                hasPlayedBismillahRef.current = true;
                playAyah(0);
            });
        }
        return;
    }

    const ayah = data.arabicAyahs[index];
    if (index >= visibleCount) setVisibleCount(prev => prev + 20);

    if (audioRef.current && ayah.audio) {
      audioRef.current.src = ayah.audio;
      audioRef.current.play().catch(() => { handleAyahEnd(); });
    } else { 
      handleAyahEnd(); 
    }
  }, [data, surahNumber, visibleCount]);

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      playAyah(currentAyahIndex);
      const ayah = data.arabicAyahs[currentAyahIndex];
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data, playAyah]);

  const handleAyahEnd = () => {
    if (isBismillahPlaying) {
        setIsBismillahPlaying(false);
        hasPlayedBismillahRef.current = true;
        playAyah(0);
        return;
    }

    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    // Large, Taj-Company style default scaling
    switch(settings.fontSize) {
      case 'sm': return 'text-3xl md:text-4xl';
      case 'lg': return 'text-5xl md:text-6xl';
      case 'xl': return 'text-6xl md:text-7xl';
      case '2xl': return 'text-7xl md:text-8xl';
      default: return 'text-4xl md:text-5xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' };
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '2.4rem' }; 
      case 'base': return { ...base, fontSize: '1.6rem', lineHeight: '2.8rem' };
      case 'lg': return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' }; 
      case 'xl': return { ...base, fontSize: '2.3rem', lineHeight: '4.0rem' };
      case '2xl': return { ...base, fontSize: '2.8rem', lineHeight: '4.8rem' };
      default: return { ...base, fontSize: '1.9rem', lineHeight: '3.4rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-20 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Drawer */}
      <div className={`fixed inset-0 z-[100] transition-all duration-500 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute bottom-0 left-0 right-0 ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-black'} rounded-t-[2.5rem] p-8 shadow-2xl transition-transform duration-500 transform ${showSettings ? 'translate-y-0' : 'translate-y-full'}`}>
            <div className="max-w-xl mx-auto">
                <div className="flex justify-between items-center mb-8">
                    <h3 className="text-2xl font-black">Settings</h3>
                    <button onClick={() => setShowSettings(false)} className="p-2 bg-black/5 rounded-2xl opacity-60 hover:opacity-100 transition-opacity"><X size={24} /></button>
                </div>
                <div className="space-y-8">
                    <div>
                        <label className="text-xs font-bold uppercase tracking-widest opacity-50 mb-3 block text-right">تھیم (Theme)</label>
                        <div className="flex gap-3">
                            {(['paper', 'sepia', 'dark'] as ThemeType[]).map(t => (
                                <button 
                                    key={t} 
                                    onClick={() => onUpdateSettings({...settings, theme: t})}
                                    className={`flex-1 py-4 rounded-2xl font-bold capitalize border-2 transition-all ${settings.theme === t ? 'border-emerald-600 bg-emerald-50/10 text-emerald-600' : 'border-black/5 text-gray-400'}`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-xs font-bold uppercase tracking-widest opacity-50 mb-3 block text-right">تحریر کا سائز (Text Size)</label>
                        <div className="flex gap-2">
                            {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map(size => (
                                <button 
                                    key={size} 
                                    onClick={() => onUpdateSettings({...settings, fontSize: size})}
                                    className={`flex-1 py-3 rounded-xl font-bold uppercase text-xs border-2 transition-all ${settings.fontSize === size ? 'border-emerald-600 bg-emerald-50/10 text-emerald-600' : 'border-black/5 text-gray-400'}`}
                                >
                                    {size}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <header ref={headerRef} className={`sticky top-0 z-50 px-6 py-4 flex items-center justify-between border-b transition-colors shadow-sm ${getThemeClasses()}`}>
        <button onClick={onBack} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><ArrowLeft size={24} /></button>
        <div className="text-center">
            <h1 className="font-arabic text-2xl text-emerald-800 leading-none mb-1 font-bold">{data?.surahInfo.name}</h1>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">{data?.surahInfo.englishName}</p>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowChat(true)} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><Sparkles size={22} /></button>
            <button onClick={() => setShowSettings(true)} className="p-2.5 text-emerald-700 bg-emerald-50 rounded-2xl active-press"><SettingsIcon size={22} /></button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 pt-12 overflow-visible">
        {/* Taj Company Style Chapter Header for Bismillah */}
        {surahNumber !== 1 && surahNumber !== 9 && (
            <div className="flex flex-col items-center mb-16 px-4">
                <div className={`text-center py-10 px-12 border-4 border-double border-emerald-900/10 rounded-[2rem] w-full max-w-2xl shadow-sm ${settings.theme === 'dark' ? 'text-emerald-400 bg-emerald-900/10' : 'text-black bg-white'}`}>
                    <p className="font-indopak text-4xl md:text-5xl leading-loose" dir="rtl">
                        {BISMILLAH_TEXT}
                    </p>
                </div>
            </div>
        )}

        <div className="space-y-12">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, idx) => {
                const tafseerAyah = data.tafseerAyahs?.[idx];
                const isCurrentAyah = currentAyahIndex === idx;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative py-12 transition-all duration-500 border-b border-gray-100 dark:border-gray-800 last:border-0 ${
                            isCurrentAyah ? 'bg-emerald-50/40 -mx-6 px-6 rounded-[3rem] ring-2 ring-emerald-500/10 shadow-xl' : ''
                        }`}
                        style={{ overflow: 'visible' }} // Ensure no marks are clipped
                    >
                        <div className="flex justify-between items-center mb-10">
                            <div className={`w-14 h-14 flex items-center justify-center rounded-2xl font-black text-lg shadow-md transition-all ${
                                isCurrentAyah ? 'bg-emerald-700 text-white scale-110' : 'bg-emerald-100 text-emerald-900'
                            }`}>
                                {ayah.numberInSurah}
                            </div>
                            <div className="flex gap-3">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-4 rounded-2xl transition-all active-press shadow-sm ${bookmarked ? 'bg-gold-500 text-white' : 'bg-white text-gray-300 hover:text-emerald-700 dark:bg-gray-800 border border-gray-100 dark:border-gray-700'}`}>
                                    {bookmarked ? <BookmarkCheck size={22} /> : <BookmarkIcon size={22} />}
                                </button>
                                <button onClick={() => { setCurrentAyahIndex(idx); setIsPlaying(true); }} className={`p-4 rounded-2xl transition-all active-press shadow-sm ${isCurrentAyah ? 'bg-emerald-900 text-white' : 'bg-white text-gray-300 hover:text-emerald-700 dark:bg-gray-800 border border-gray-100 dark:border-gray-700'}`}>
                                    {isCurrentAyah && isPlaying ? <Pause size={22} /> : <Play size={22} />}
                                </button>
                            </div>
                        </div>

                        {/* Taj Quran Thick Black Arabic Text with no clipping */}
                        <div className="text-right mb-16 px-2" dir="rtl" style={{ overflow: 'visible' }}>
                            <p className={`font-indopak ${getFontClasses()}`} style={{ display: 'inline-block', width: '100%', whiteSpace: 'normal' }}>
                                {ayah.text} <span className="text-emerald-900/10 mx-4 select-none">۝</span>
                            </p>
                        </div>

                        {/* Bold Urdu Nastaliq Translation */}
                        {settings.showTafseer && tafseerAyah && (
                            <div className="text-right border-r-8 border-emerald-900/10 pr-10 mb-4" dir="rtl">
                                <p 
                                    className={`font-urdu transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-emerald-50' : 'text-gray-900'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}
            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-60 flex flex-col items-center justify-center gap-4">
                 <Loader2 className="animate-spin text-emerald-700" size={48} />
                 <p className="text-[10px] font-black text-emerald-800/40 uppercase tracking-[0.3em]">Next 20 Ayahs...</p>
              </div>
            )}
        </div>
      </main>

      {isPlaying && (
          <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 z-[60] bg-emerald-950/95 text-white px-8 py-5 rounded-[2.5rem] shadow-2xl flex items-center gap-8 border border-white/20 backdrop-blur-2xl transition-all">
             <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-2.5 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipBack size={24} /></button>
             <button onClick={() => setIsPlaying(!isPlaying)} className="w-14 h-14 flex items-center justify-center bg-gold-500 text-emerald-950 rounded-full shadow-2xl active-press group">
                {isPlaying ? <Pause size={28} className="fill-current" /> : <Play size={28} className="fill-current" />}
             </button>
             <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-2.5 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipForward size={24} /></button>
             <div className="h-10 w-px bg-white/20 mx-2"></div>
             <button onClick={() => { setIsPlaying(false); setCurrentAyahIndex(-1); }} className="p-2.5 opacity-60 hover:text-red-400 hover:opacity-100 active-press"><X size={24} /></button>
          </div>
      )}

      <AIChat 
        isOpen={showChat} 
        onClose={() => setShowChat(false)} 
        context={`Reading Surah ${data?.surahInfo.englishName} in the authentic Taj Quran Lahore style. Currently at Ayah ${currentAyahIndex + 1}.`} 
      />
    </div>
  );
};

export default Reader;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  Settings as SettingsIcon, X, Moon, Sun, Type, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

const BISMILLAH_TEXT = "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ";
const BISMILLAH_AUDIO = "https://cdn.islamic.network/quran/audio/128/ar.alafasy/1.mp3";

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isBismillahPlaying, setIsBismillahPlaying] = useState(false);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hasPlayedBismillahRef = useRef<boolean>(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '600px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsBismillahPlaying(false);
      hasPlayedBismillahRef.current = false;

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const playAyah = useCallback((index: number) => {
    if (!data) return;

    if (index === 0 && surahNumber !== 9 && surahNumber !== 1 && !hasPlayedBismillahRef.current) {
        setIsBismillahPlaying(true);
        if (audioRef.current) {
            audioRef.current.src = BISMILLAH_AUDIO;
            audioRef.current.play().catch(() => {
                setIsBismillahPlaying(false);
                hasPlayedBismillahRef.current = true;
                playAyah(0);
            });
        }
        return;
    }

    const ayah = data.arabicAyahs[index];
    if (index >= visibleCount) setVisibleCount(prev => prev + 20);

    if (audioRef.current && ayah.audio) {
      audioRef.current.src = ayah.audio;
      audioRef.current.play().catch(() => { handleAyahEnd(); });
    } else { 
      handleAyahEnd(); 
    }
  }, [data, surahNumber, visibleCount]);

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      playAyah(currentAyahIndex);
      const ayah = data.arabicAyahs[currentAyahIndex];
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data, playAyah]);

  const handleAyahEnd = () => {
    if (isBismillahPlaying) {
        setIsBismillahPlaying(false);
        hasPlayedBismillahRef.current = true;
        playAyah(0);
        return;
    }

    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    // Large, authentic Taj-Company scaling
    switch(settings.fontSize) {
      case 'sm': return 'text-3xl md:text-4xl';
      case 'lg': return 'text-5xl md:text-6xl';
      case 'xl': return 'text-6xl md:text-7xl';
      case '2xl': return 'text-7xl md:text-8xl';
      default: return 'text-4xl md:text-5xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' };
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '2.8rem' }; 
      case 'base': return { ...base, fontSize: '1.7rem', lineHeight: '3.2rem' };
      case 'lg': return { ...base, fontSize: '2.0rem', lineHeight: '3.6rem' }; 
      case 'xl': return { ...base, fontSize: '2.4rem', lineHeight: '4.2rem' };
      case '2xl': return { ...base, fontSize: '3.0rem', lineHeight: '5.2rem' };
      default: return { ...base, fontSize: '2.0rem', lineHeight: '3.6rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-24 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      {/* Settings Drawer */}
      <div className={`fixed inset-0 z-[100] transition-all duration-500 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/50 backdrop-blur-md" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute bottom-0 left-0 right-0 ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-black'} rounded-t-[3rem] p-10 shadow-2xl transition-transform duration-500 transform ${showSettings ? 'translate-y-0' : 'translate-y-full'}`}>
            <div className="max-w-2xl mx-auto">
                <div className="flex justify-between items-center mb-10">
                    <h3 className="text-3xl font-black">Settings</h3>
                    <button onClick={() => setShowSettings(false)} className="p-3 bg-black/5 rounded-2xl hover:bg-black/10 transition-colors"><X size={28} /></button>
                </div>
                <div className="space-y-10">
                    <div>
                        <label className="text-sm font-black uppercase tracking-[0.2em] opacity-40 mb-4 block text-right">تھیم (Theme)</label>
                        <div className="flex gap-4">
                            {(['paper', 'sepia', 'dark'] as ThemeType[]).map(t => (
                                <button 
                                    key={t} 
                                    onClick={() => onUpdateSettings({...settings, theme: t})}
                                    className={`flex-1 py-5 rounded-3xl font-bold capitalize border-2 transition-all shadow-sm ${settings.theme === t ? 'border-emerald-600 bg-emerald-50 text-emerald-700' : 'border-gray-100 text-gray-400 bg-gray-50'}`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-sm font-black uppercase tracking-[0.2em] opacity-40 mb-4 block text-right">تحریر کا سائز (Font Size)</label>
                        <div className="flex gap-3">
                            {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map(size => (
                                <button 
                                    key={size} 
                                    onClick={() => onUpdateSettings({...settings, fontSize: size})}
                                    className={`flex-1 py-4 rounded-2xl font-black uppercase text-xs border-2 transition-all ${settings.fontSize === size ? 'border-emerald-600 bg-emerald-50 text-emerald-700 shadow-sm' : 'border-gray-100 text-gray-400 bg-gray-50'}`}
                                >
                                    {size}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <header ref={headerRef} className={`sticky top-0 z-50 px-6 py-5 flex items-center justify-between border-b transition-colors shadow-lg backdrop-blur-md ${getThemeClasses()}`}>
        <button onClick={onBack} className="p-3 text-emerald-800 bg-emerald-100/50 hover:bg-emerald-100 rounded-2xl active-press transition-all"><ArrowLeft size={24} /></button>
        <div className="text-center">
            <h1 className="font-arabic text-3xl text-emerald-900 leading-none mb-1 font-bold">{data?.surahInfo.name}</h1>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em]">{data?.surahInfo.englishName}</p>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowChat(true)} className="p-3 text-emerald-800 bg-emerald-100/50 hover:bg-emerald-100 rounded-2xl active-press transition-all"><Sparkles size={24} /></button>
            <button onClick={() => setShowSettings(true)} className="p-3 text-emerald-800 bg-emerald-100/50 hover:bg-emerald-100 rounded-2xl active-press transition-all"><SettingsIcon size={24} /></button>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 pt-16 overflow-visible">
        {/* TAJ COMPANY STYLE CHAPTER HEAD */}
        {surahNumber !== 1 && surahNumber !== 9 && (
            <div className="flex flex-col items-center mb-20 px-4">
                <div className={`text-center py-12 px-14 border-8 border-double border-emerald-900/10 rounded-[3rem] w-full max-w-3xl shadow-xl ${settings.theme === 'dark' ? 'text-emerald-400 bg-emerald-900/10' : 'text-black bg-white/50'}`}>
                    <p className="font-indopak text-4xl md:text-6xl" dir="rtl">
                        {BISMILLAH_TEXT}
                    </p>
                </div>
            </div>
        )}

        <div className="space-y-4">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, idx) => {
                const tafseerAyah = data.tafseerAyahs?.[idx];
                const isCurrentAyah = currentAyahIndex === idx;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative py-12 transition-all duration-700 border-b border-gray-100 dark:border-gray-800 last:border-0 ${
                            isCurrentAyah ? 'bg-emerald-50/60 -mx-8 px-8 rounded-[4rem] ring-4 ring-emerald-500/5 shadow-2xl z-10' : ''
                        }`}
                        style={{ overflow: 'visible' }} // ABSOLUTELY ESSENTIAL: Do not clip marks
                    >
                        <div className="flex justify-between items-center mb-6">
                            <div className={`w-16 h-16 flex items-center justify-center rounded-[1.5rem] font-black text-xl shadow-lg transition-all duration-500 ${
                                isCurrentAyah ? 'bg-emerald-800 text-white scale-125 rotate-6' : 'bg-emerald-100 text-emerald-900 rotate-0'
                            }`}>
                                {ayah.numberInSurah}
                            </div>
                            <div className="flex gap-4">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-4 rounded-2xl transition-all active-press shadow-md ${bookmarked ? 'bg-gold-500 text-white' : 'bg-white text-gray-300 hover:text-emerald-700 dark:bg-gray-800 border border-gray-100'}`}>
                                    {bookmarked ? <BookmarkCheck size={26} /> : <BookmarkIcon size={26} />}
                                </button>
                                <button onClick={() => { setCurrentAyahIndex(idx); setIsPlaying(true); }} className={`p-4 rounded-2xl transition-all active-press shadow-md ${isCurrentAyah ? 'bg-emerald-900 text-white' : 'bg-white text-gray-300 hover:text-emerald-700 dark:bg-gray-800 border border-gray-100'}`}>
                                    {isCurrentAyah && isPlaying ? <Pause size={26} /> : <Play size={26} />}
                                </button>
                            </div>
                        </div>

                        {/* TAJ QURAN SCRIPT RENDER - NO CLIPPING */}
                        <div className="text-right mb-16 px-4" dir="rtl" style={{ overflow: 'visible' }}>
                            <p className={`font-indopak ${getFontClasses()}`} style={{ width: '100%', wordBreak: 'keep-all' }}>
                                {ayah.text} <span className="text-emerald-900/10 mx-6 select-none inline-block align-middle transform translate-y-2">۝</span>
                            </p>
                        </div>

                        {/* BOLD URDU NASTALIQ - NO CLIPPING */}
                        {settings.showTafseer && tafseerAyah && (
                            <div className="text-right border-r-[12px] border-emerald-900/10 pr-12 mb-6" dir="rtl" style={{ overflow: 'visible' }}>
                                <p 
                                    className={`font-urdu transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-emerald-50' : 'text-gray-900'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}

            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-96 flex flex-col items-center justify-center gap-6">
                 <Loader2 className="animate-spin text-emerald-800" size={64} />
                 <p className="text-xs font-black text-emerald-800/30 uppercase tracking-[0.5em]">Continuing the Revelation</p>
              </div>
            )}
        </div>
      </main>

      {/* Floating Control Bar */}
      {isPlaying && (
          <div className="fixed bottom-10 left-1/2 transform -translate-x-1/2 z-[70] bg-emerald-950/95 text-white px-10 py-6 rounded-[3rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.6)] flex items-center gap-10 border border-white/20 backdrop-blur-3xl transition-all scale-110">
             <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-3 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipBack size={28} /></button>
             <button onClick={() => setIsPlaying(!isPlaying)} className="w-16 h-16 flex items-center justify-center bg-gold-500 text-emerald-950 rounded-full shadow-2xl active-press group hover:scale-105 transition-transform">
                {isPlaying ? <Pause size={32} className="fill-current" /> : <Play size={32} className="fill-current" />}
             </button>
             <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-3 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipForward size={28} /></button>
             <div className="h-12 w-px bg-white/20 mx-2"></div>
             <button onClick={() => { setIsPlaying(false); setCurrentAyahIndex(-1); }} className="p-3 opacity-60 hover:text-red-400 hover:opacity-100 active-press"><X size={28} /></button>
          </div>
      )}

      <AIChat 
        isOpen={showChat} 
        onClose={() => setShowChat(false)} 
        context={`Reading Surah ${data?.surahInfo.englishName} in the authentic Taj Quran Lahore style. Currently at Ayah ${currentAyahIndex + 1}.`} 
      />
    </div>
  );
};

export default Reader;

