interface QiblaFinderProps {
  onClose: () => void;
}

const QiblaFinder: React.FC<QiblaFinderProps> = ({ onClose }) => {
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [qibla, setQibla] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);

  const calculateQibla = (lat: number, lng: number) => {
    const PI = Math.PI;
    const latK = 21.422487 * (PI / 180);
    const lngK = 39.826206 * (PI / 180);
    const phi = lat * (PI / 180);
    const lambda = lng * (PI / 180);
    const y = Math.sin(lngK - lambda);
    const x = Math.cos(phi) * Math.tan(latK) - Math.sin(phi) * Math.cos(lngK - lambda);
    let angle = Math.atan2(y, x) * (180 / PI);
    return (angle + 360) % 360;
  };

  useEffect(() => {
    if (!navigator.geolocation) {
      setError("Geolocation is not supported by your browser.");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setCoords({ lat: latitude, lng: longitude });
        setQibla(calculateQibla(latitude, longitude));
      },
      (err) => {
        setError("Location access is disabled. Please turn on Location in your computer/browser settings to find the Qibla direction.");
      }
    );
  }, []);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose}></div>
      <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md relative z-10 overflow-hidden border border-gray-200">
        <div className="bg-black p-8 text-white flex justify-between items-center">
          <h3 className="text-2xl font-bold flex items-center gap-2">
            <Compass className="text-emerald-400" /> قبله ڈائریکشن
          </h3>
          <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <X size={24} />
          </button>
        </div>

        <div className="p-10 text-center">
          {error ? (
            <div className="flex flex-col items-center">
              <AlertCircle size={64} className="text-red-500 mb-4" />
              <p className="text-gray-800 font-bold mb-4">{error}</p>
              <button 
                onClick={() => window.location.reload()}
                className="bg-black text-white px-8 py-3 rounded-2xl font-bold shadow-lg active-press"
              >
                کوشش دوبارہ کریں
              </button>
            </div>
          ) : !qibla ? (
            <div className="flex flex-col items-center">
              <div className="w-16 h-16 border-4 border-gray-100 border-t-black rounded-full animate-spin mb-4"></div>
              <p className="text-gray-500 font-bold">مقام تلاش کیا جا رہا ہے...</p>
            </div>
          ) : (
            <div className="flex flex-col items-center">
              <div className="relative w-64 h-64 mb-8">
                <div className="absolute inset-0 border-[12px] border-gray-100 rounded-full shadow-inner"></div>
                <div 
                  className="absolute inset-0 flex items-center justify-center transition-transform duration-1000"
                  style={{ transform: `rotate(${qibla}deg)` }}
                >
                  <Navigation size={64} className="text-black fill-current" />
                </div>
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="w-2 h-2 bg-black rounded-full"></div>
                </div>
              </div>

              <div className="bg-gray-50 p-6 rounded-[2rem] border border-gray-100 w-full">
                <h4 className="text-3xl font-black text-black mb-1">{Math.round(qibla)}°</h4>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Qibla Angle from North</p>
              </div>

              <p className="mt-6 text-sm text-gray-500 font-bold leading-relaxed px-4">
                اپنے فون یا کمپیوٹر کو ہموار سطح پر رکھیں اور اوپر دیے گئے نشان کو کعبہ کی طرف موڑیں۔
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

