  const [loading, setLoading] = useState(true);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showChat, setShowChat] = useState(false);
  const [showQibla, setShowQibla] = useState(false);

  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadProgress, setDownloadProgress] = useState(0);
  const [showDownloadModal, setShowDownloadModal] = useState(false);
  const [downloadCompleted, setDownloadCompleted] = useState(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const list = await getSurahList();
        setSurahs(list);
        setFilteredSurahs(list);

        const saved = localStorage.getItem('quran_bookmarks');
        if (saved) setBookmarks(JSON.parse(saved));
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const lowerSearch = search.toLowerCase();
    const filtered = surahs.filter(
      (s) =>
        s.englishName.toLowerCase().includes(lowerSearch) ||
        s.englishNameTranslation.toLowerCase().includes(lowerSearch) ||
        s.number.toString().includes(lowerSearch) ||
        s.name.includes(search)
    );
    setFilteredSurahs(filtered);
  }, [search, surahs]);

  const deleteBookmark = (e: React.MouseEvent, ts: number) => {
    e.stopPropagation();
    const updated = bookmarks.filter(b => b.timestamp !== ts);
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const handleDownload = async () => {
    if (!isOnline) return;
    setIsDownloading(true);
    setDownloadProgress(0);
    setDownloadCompleted(false);

    try {
      await downloadQuranData(settings.script, (progress) => {
        setDownloadProgress(progress);
      });
      setDownloadCompleted(true);
    } catch (error) {
      console.error("Download failed", error);
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="min-h-screen bg-paper flex flex-col">
      {!isOnline && (
        <div className="sticky top-0 z-50 bg-amber-500 text-white text-[10px] py-1 text-center font-bold uppercase tracking-widest flex items-center justify-center">
            <WifiOff size={10} className="mr-1" /> Browsing Offline
        </div>
      )}

      <div className="bg-emerald-900 text-white pt-6 pb-24 px-6 relative overflow-hidden flex-shrink-0">
        <div className="absolute top-0 right-0 w-80 h-80 bg-emerald-800 rounded-full mix-blend-multiply filter blur-3xl opacity-20 -translate-y-1/2 translate-x-1/2"></div>

        <div className="max-w-5xl mx-auto relative z-10">
          <div className="flex justify-between items-center mb-10">
            <div className="flex items-center gap-2">
                 <button onClick={() => setShowChat(true)} className="flex items-center gap-2 bg-emerald-800/40 text-emerald-100 hover:text-white hover:bg-emerald-700/50 px-4 py-2.5 rounded-2xl transition-all text-xs font-bold border border-emerald-700/50 shadow-sm active-press">
                    <Sparkles size={16} className="text-gold-400" />
                    <span className="hidden sm:inline">AI Scholar</span>
                </button>
                <button onClick={() => setShowQibla(true)} className="flex items-center gap-2 bg-emerald-800/40 text-emerald-100 hover:text-white hover:bg-emerald-700/50 px-4 py-2.5 rounded-2xl transition-all text-xs font-bold border border-emerald-700/50 shadow-sm active-press">
                    <Compass size={16} />
                    <span className="hidden sm:inline">Qibla</span>
                </button>
                <button onClick={() => setShowDownloadModal(true)} className="flex items-center gap-2 bg-emerald-800/40 text-emerald-100 hover:text-white hover:bg-emerald-700/50 px-4 py-2.5 rounded-2xl transition-all text-xs font-bold border border-emerald-700/50 shadow-sm active-press">
                    <CloudDownload size={16} />
                    <span className="hidden sm:inline">Download</span>
                </button>
            </div>

            <button onClick={onGoToAbout} className="p-2.5 text-emerald-300 hover:text-white transition-colors bg-emerald-800/40 rounded-2xl border border-emerald-700/50 active-press">
              <Info size={22} />
            </button>
          </div>

          <div className="text-center">
            <h1 className="font-arabic text-6xl md:text-7xl mb-4 text-gold-400 drop-shadow-2xl">القرآن الكريم</h1>
            <p className="text-emerald-100 text-sm md:text-base font-medium tracking-widest uppercase opacity-80 mb-8">The Holy Quran Urdu Translation</p>

            <div className="relative max-w-xl mx-auto">
              <input
                type="text"
                placeholder="سورت تلاش کریں (Search Surah...)"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full py-5 px-8 pr-16 rounded-[2rem] bg-white text-black placeholder-gray-400 focus:outline-none focus:ring-4 focus:ring-black/10 shadow-2xl transition-all text-right font-urdu text-lg"
                dir="rtl"
              />
              <Search className="absolute right-6 top-1/2 transform -translate-y-1/2 text-black" size={24} />
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 max-w-7xl mx-auto w-full px-4 -mt-12 relative z-20 pb-10 flex flex-col min-h-0">
        {bookmarks.length > 0 && !search && (
            <div className="mb-8 flex-shrink-0 overflow-hidden">
                <div className="flex items-center gap-3 mb-4 text-black px-2">
                    <BookmarkIcon size={20} className="text-gold-500" fill="currentColor" />
                    <h2 className="text-lg font-bold">نشانی (Bookmarks)</h2>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-4 px-2 no-scrollbar">
                    {bookmarks.map((b) => (
                        <div key={b.timestamp} onClick={() => onSelectSurah(b.surahNumber, b.ayahNumber)} className="flex-shrink-0 w-52 bg-white border border-gold-200 hover:border-gold-500 rounded-3xl p-5 shadow-lg transition-all cursor-pointer group active-press">
                            <div className="flex justify-between items-start mb-3">
                                <span className="text-[10px] font-black bg-gold-50 text-gold-700 px-2.5 py-1 rounded-lg uppercase tracking-wider">Ayah {b.ayahNumber}</span>
                                <button onClick={(e) => deleteBookmark(e, b.timestamp)} className="p-1.5 text-gray-300 hover:text-red-500 bg-gray-50 rounded-full"><Trash2 size={16} /></button>
                            </div>
                            <h3 className="font-bold text-gray-800 text-base truncate">{b.surahName}</h3>
                        </div>
                    ))}
                </div>
            </div>
        )}

        <div className="flex-1 bg-white rounded-[2.5rem] shadow-2xl border border-gray-100 overflow-hidden flex flex-col min-h-0">
            <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white/95 backdrop-blur-md z-10">
                <div className="flex items-center gap-3 text-black">
                    <Book size={24} className="text-black" />
                    <h2 className="text-xl font-bold">سورت انڈیکس</h2>
                </div>
                <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest bg-gray-50 px-3 py-1 rounded-full">
                    {filteredSurahs.length} Chapters
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 sm:p-6 custom-scrollbar">
                {loading ? (
                  <LoadingSpinner />
                ) : filteredSurahs.length > 0 ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {filteredSurahs.map((surah) => (
                      <div 
                        key={surah.number} 
                        onClick={() => onSelectSurah(surah.number)} 
                        className="bg-white hover:bg-gray-50 border border-gray-100 hover:border-black/10 rounded-[1.5rem] p-4 shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer group flex items-center justify-between min-h-[90px] active-press surah-card"
                      >
                        <div className="flex items-center gap-4 min-w-0">
                          <div className="w-11 h-11 relative flex items-center justify-center flex-shrink-0">
                             <div className="absolute inset-0 bg-gray-100 rounded-2xl transform rotate-45 group-hover:rotate-90 group-hover:bg-black group-hover:text-white transition-all duration-500 shadow-sm"></div>
                             <span className="relative font-black text-black group-hover:text-white text-xs transition-colors">{surah.number}</span>
                          </div>
                          <div className="min-w-0">
                            <h3 className="font-bold text-gray-800 group-hover:text-black text-base truncate transition-colors leading-tight mb-1">
                                {surah.englishName}
                            </h3>
                            <p className="text-[10px] text-gray-400 uppercase font-bold tracking-tight truncate opacity-80 group-hover:opacity-100 transition-opacity">
                                {surah.englishNameTranslation}
                            </p>
                          </div>
                        </div>
                        <div className="text-right flex-shrink-0 pl-2">
                            <h3 className="font-arabic text-xl text-black mb-0.5 group-hover:scale-105 transition-transform origin-right">{surah.name}</h3>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{surah.numberOfAyahs} Ayat</p>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center py-20 text-gray-400">
                    <Search size={64} className="mb-6 opacity-10" />
                    <p className="text-xl font-medium">No results found for "{search}"</p>
                  </div>
                )}
            </div>
        </div>
      </div>

      {showDownloadModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => !isDownloading && setShowDownloadModal(false)}></div>
            <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md relative z-10 overflow-hidden border border-white">
                <div className="bg-black p-8 text-white relative">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/2"></div>
                    <div className="flex justify-between items-center relative z-10">
                        <h3 className="text-2xl font-bold flex items-center">
                            <Download size={28} className="mr-3" /> Offline Sync
                        </h3>
                        {!isDownloading && (
                            <button onClick={() => setShowDownloadModal(false)} className="hover:bg-white/10 p-2 rounded-2xl transition-all">
                                <X size={24} />
                            </button>
                        )}
                    </div>
                </div>

                <div className="p-10">
                    {downloadCompleted ? (
                        <div className="text-center">
                            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6 text-black shadow-inner">
                                <CheckCircle2 size={40} />
                            </div>
                            <h4 className="text-2xl font-bold text-gray-800 mb-2">Sync Complete</h4>
                            <p className="text-gray-500 text-sm mb-8">Quran text and Urdu translations are now stored locally.</p>
                            <button onClick={() => setShowDownloadModal(false)} className="bg-black text-white px-8 py-4 rounded-2xl font-bold hover:bg-gray-900 transition-all w-full shadow-lg active-press">
                                Done
                            </button>
                        </div>
                    ) : isDownloading ? (
                        <div className="text-center">
                            <div className="w-full bg-gray-100 rounded-full h-3 mb-6 overflow-hidden border border-gray-100">
                                <div className="bg-black h-full transition-all duration-300" style={{ width: `${downloadProgress}%` }}></div>
                            </div>
                            <h4 className="text-3xl font-black text-black mb-2">{downloadProgress}%</h4>
                            <p className="text-sm font-bold text-gray-400 uppercase tracking-widest">Caching Holy Verses...</p>
                        </div>
                    ) : (
                        <div className="text-center">
                            <div className="p-6 bg-gray-50 rounded-3xl mb-8 border border-gray-100 text-gray-900 text-sm font-medium leading-relaxed">
                                This will store all 114 Surahs (Text, Urdu Translation, and Tafseer) on your device (~25MB).
                            </div>
                            <button 
                                onClick={handleDownload}
                                disabled={!isOnline}
                                className="bg-black text-white px-8 py-4 rounded-2xl font-bold hover:bg-gray-900 transition-all w-full flex items-center justify-center shadow-lg disabled:opacity-50 active-press"
                            >
                                <CloudDownload size={24} className="mr-3" />
                                {isOnline ? 'Download Now' : 'Connect to Internet'}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
      )}

      {showQibla && <QiblaFinder onClose={() => setShowQibla(false)} />}
      <AIChat context="User is browsing Surah Index" isOpen={showChat} onClose={() => setShowChat(false)} />
    </div>
  );
};

export default SurahList;

import React, { useEffect, useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, Play, Pause, SkipForward, SkipBack, Volume2, 
  Loader2, Bookmark as BookmarkIcon, BookmarkCheck, 
  Settings as SettingsIcon, X, Moon, Sun, Type, Sparkles
} from 'lucide-react';
import { CombinedSurahData, Bookmark, AppSettings, FontSize, ThemeType } from '../types';
import { getSurahDetails } from '../services/quranApi';
import LoadingSpinner from './LoadingSpinner';
import AIChat from './AIChat';

const BISMILLAH_TEXT = "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ";
const BISMILLAH_AUDIO = "https://cdn.islamic.network/quran/audio/128/ar.alafasy/1.mp3";

interface ReaderProps {
  surahNumber: number;
  initialAyah?: number;
  onBack: () => void;
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
}

const Reader: React.FC<ReaderProps> = ({ surahNumber, initialAyah, onBack, settings, onUpdateSettings }) => {
  const [data, setData] = useState<CombinedSurahData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentAyahIndex, setCurrentAyahIndex] = useState<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showSettings, setShowSettings] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isBismillahPlaying, setIsBismillahPlaying] = useState(false);

  const [visibleCount, setVisibleCount] = useState(20);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const hasPlayedBismillahRef = useRef<boolean>(false);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('quran_bookmarks');
    if (saved) setBookmarks(JSON.parse(saved));
  }, []);

  useEffect(() => {
    if (!data || loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
           setVisibleCount((prev) => Math.min(prev + 20, data.arabicAyahs.length));
        }
      },
      { rootMargin: '600px' }
    );
    if (loadMoreRef.current) observer.observe(loadMoreRef.current);
    return () => { if (loadMoreRef.current) observer.unobserve(loadMoreRef.current); };
  }, [data, loading, visibleCount]);

  useEffect(() => {
    let isMounted = true;
    const fetchDetails = async () => {
      setLoading(true);
      setError(null);
      setCurrentAyahIndex(-1);
      setIsPlaying(false);
      setIsBismillahPlaying(false);
      hasPlayedBismillahRef.current = false;

      try {
        const result = await getSurahDetails(surahNumber, settings.script);
        if (isMounted) {
          setData(result);
          if (initialAyah) {
            setVisibleCount(Math.max(20, initialAyah + 5));
            setTimeout(() => {
                const element = document.getElementById(`ayah-${initialAyah}`);
                if (element) {
                    element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
          } else {
            setVisibleCount(20);
            window.scrollTo(0, 0);
          }
        }
      } catch (err) {
        if (isMounted) setError('Failed to load surah content.');
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchDetails();
    return () => { isMounted = false; };
  }, [surahNumber, settings.script]);

  const toggleBookmark = (ayahNumberInSurah: number) => {
    if (!data) return;
    const isBookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah);
    const updated = isBookmarked 
      ? bookmarks.filter(b => !(b.surahNumber === surahNumber && b.ayahNumber === ayahNumberInSurah))
      : [{ surahNumber, ayahNumber: ayahNumberInSurah, surahName: data.surahInfo.englishName, timestamp: Date.now() }, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('quran_bookmarks', JSON.stringify(updated));
  };

  const playAyah = useCallback((index: number) => {
    if (!data) return;

    if (index === 0 && surahNumber !== 9 && surahNumber !== 1 && !hasPlayedBismillahRef.current) {
        setIsBismillahPlaying(true);
        if (audioRef.current) {
            audioRef.current.src = BISMILLAH_AUDIO;
            audioRef.current.play().catch(() => {
                setIsBismillahPlaying(false);
                hasPlayedBismillahRef.current = true;
                playAyah(0);
            });
        }
        return;
    }

    const ayah = data.arabicAyahs[index];
    if (index >= visibleCount) setVisibleCount(prev => prev + 20);

    if (audioRef.current && ayah.audio) {
      audioRef.current.src = ayah.audio;
      audioRef.current.play().catch(() => { handleAyahEnd(); });
    } else { 
      handleAyahEnd(); 
    }
  }, [data, surahNumber, visibleCount]);

  useEffect(() => {
    if (currentAyahIndex !== -1 && data) {
      playAyah(currentAyahIndex);
      const ayah = data.arabicAyahs[currentAyahIndex];
      setTimeout(() => {
        const element = document.getElementById(`ayah-${ayah.numberInSurah}`);
        if (element) element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  }, [currentAyahIndex, data, playAyah]);

  const handleAyahEnd = () => {
    if (isBismillahPlaying) {
        setIsBismillahPlaying(false);
        hasPlayedBismillahRef.current = true;
        playAyah(0);
        return;
    }

    if (data && currentAyahIndex < data.arabicAyahs.length - 1) {
        setCurrentAyahIndex(prev => prev + 1);
    } else {
        setIsPlaying(false);
        setCurrentAyahIndex(-1);
    }
  };

  const getThemeClasses = () => {
    switch(settings.theme) {
      case 'dark': return 'bg-gray-900 border-gray-800 text-white';
      case 'sepia': return 'bg-[#fdf6e3] border-[#eee8d5] text-black';
      default: return 'bg-white border-gray-100 text-black';
    }
  };

  const getFontClasses = () => {
    switch(settings.fontSize) {
      case 'sm': return 'text-3xl md:text-4xl';
      case 'lg': return 'text-5xl md:text-6xl';
      case 'xl': return 'text-6xl md:text-7xl';
      case '2xl': return 'text-7xl md:text-8xl';
      default: return 'text-4xl md:text-5xl';
    }
  };

  const getTafseerStyle = () => {
    const base = { fontWeight: '700' };
    switch(settings.tafseerFontSize) {
      case 'sm': return { ...base, fontSize: '1.4rem', lineHeight: '2.8rem' }; 
      case 'base': return { ...base, fontSize: '1.7rem', lineHeight: '3.2rem' };
      case 'lg': return { ...base, fontSize: '2.0rem', lineHeight: '3.6rem' }; 
      case 'xl': return { ...base, fontSize: '2.4rem', lineHeight: '4.2rem' };
      case '2xl': return { ...base, fontSize: '3.0rem', lineHeight: '5.2rem' };
      default: return { ...base, fontSize: '2.0rem', lineHeight: '3.6rem' };
    }
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className={`min-h-screen pb-24 relative transition-colors duration-300 ${
      settings.theme === 'dark' ? 'bg-gray-950' : settings.theme === 'sepia' ? 'bg-[#f4ecd8]' : 'bg-paper'
    }`}>
      <audio ref={audioRef} onEnded={handleAyahEnd} onError={handleAyahEnd} />

      <div className={`fixed inset-0 z-[100] transition-all duration-500 ${showSettings ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
        <div className="absolute inset-0 bg-black/50 backdrop-blur-md" onClick={() => setShowSettings(false)}></div>
        <div className={`absolute bottom-0 left-0 right-0 ${settings.theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-white text-black'} rounded-t-[3rem] p-10 shadow-2xl transition-transform duration-500 transform ${showSettings ? 'translate-y-0' : 'translate-y-full'}`}>
            <div className="max-w-2xl mx-auto">
                <div className="flex justify-between items-center mb-10">
                    <h3 className="text-3xl font-black">Settings</h3>
                    <button onClick={() => setShowSettings(false)} className="p-3 bg-black/5 rounded-2xl hover:bg-black/10 transition-colors"><X size={28} /></button>
                </div>
                <div className="space-y-10">
                    <div>
                        <label className="text-sm font-black uppercase tracking-[0.2em] opacity-40 mb-4 block text-right">تھیم (Theme)</label>
                        <div className="flex gap-4">
                            {(['paper', 'sepia', 'dark'] as ThemeType[]).map(t => (
                                <button 
                                    key={t} 
                                    onClick={() => onUpdateSettings({...settings, theme: t})}
                                    className={`flex-1 py-5 rounded-3xl font-bold capitalize border-2 transition-all shadow-sm ${settings.theme === t ? 'border-black bg-black text-white' : 'border-gray-100 text-gray-400 bg-gray-50'}`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-sm font-black uppercase tracking-[0.2em] opacity-40 mb-4 block text-right">تحریر کا سائز (Font Size)</label>
                        <div className="flex gap-3">
                            {(['sm', 'base', 'lg', 'xl', '2xl'] as FontSize[]).map(size => (
                                <button 
                                    key={size} 
                                    onClick={() => onUpdateSettings({...settings, fontSize: size})}
                                    className={`flex-1 py-4 rounded-2xl font-black uppercase text-xs border-2 transition-all ${settings.fontSize === size ? 'border-black bg-black text-white shadow-sm' : 'border-gray-100 text-gray-400 bg-gray-50'}`}
                                >
                                    {size}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <header ref={headerRef} className={`sticky top-0 z-50 px-6 py-5 flex items-center justify-between border-b transition-colors shadow-lg backdrop-blur-md ${getThemeClasses()}`}>
        <button onClick={onBack} className="p-3 text-black bg-gray-100 hover:bg-gray-200 rounded-2xl active-press transition-all"><ArrowLeft size={24} /></button>
        <div className="text-center">
            <h1 className="font-arabic text-3xl text-black leading-none mb-1 font-bold">{data?.surahInfo.name}</h1>
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.25em]">{data?.surahInfo.englishName}</p>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowChat(true)} className="p-3 text-black bg-gray-100 hover:bg-gray-200 rounded-2xl active-press transition-all"><Sparkles size={24} /></button>
            <button onClick={() => setShowSettings(true)} className="p-3 text-black bg-gray-100 hover:bg-gray-200 rounded-2xl active-press transition-all"><SettingsIcon size={24} /></button>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 pt-16 overflow-visible">
        {surahNumber !== 1 && surahNumber !== 9 && (
            <div className="flex flex-col items-center mb-20 px-4">
                <div className={`text-center py-12 px-14 border-8 border-double border-black/10 rounded-[3rem] w-full max-w-3xl shadow-xl ${settings.theme === 'dark' ? 'text-emerald-400 bg-emerald-900/10' : 'text-black bg-white/50'}`}>
                    <p className="font-indopak text-4xl md:text-6xl" dir="rtl">
                        {BISMILLAH_TEXT}
                    </p>
                </div>
            </div>
        )}

        <div className="space-y-4">
            {data?.arabicAyahs.slice(0, visibleCount).map((ayah, idx) => {
                const tafseerAyah = data.tafseerAyahs?.[idx];
                const isCurrentAyah = currentAyahIndex === idx;
                const bookmarked = bookmarks.some(b => b.surahNumber === surahNumber && b.ayahNumber === ayah.numberInSurah);

                return (
                    <div 
                        key={ayah.number} 
                        id={`ayah-${ayah.numberInSurah}`}
                        className={`group relative py-12 transition-all duration-700 border-b border-gray-100 dark:border-gray-800 last:border-0 ${
                            isCurrentAyah ? 'bg-gray-50/60 -mx-8 px-8 rounded-[4rem] ring-4 ring-black/5 shadow-2xl z-10' : ''
                        }`}
                        style={{ overflow: 'visible' }}
                    >
                        <div className="flex justify-between items-center mb-6">
                            <div className={`w-16 h-16 flex items-center justify-center rounded-[1.5rem] font-black text-xl shadow-lg transition-all duration-500 ${
                                isCurrentAyah ? 'bg-black text-white scale-125 rotate-6' : 'bg-gray-100 text-black rotate-0'
                            }`}>
                                {ayah.numberInSurah}
                            </div>
                            <div className="flex gap-4">
                                <button onClick={() => toggleBookmark(ayah.numberInSurah)} className={`p-4 rounded-2xl transition-all active-press shadow-md ${bookmarked ? 'bg-gold-500 text-white' : 'bg-white text-gray-300 hover:text-black dark:bg-gray-800 border border-gray-100'}`}>
                                    {bookmarked ? <BookmarkCheck size={26} /> : <BookmarkIcon size={26} />}
                                </button>
                                <button onClick={() => { setCurrentAyahIndex(idx); setIsPlaying(true); }} className={`p-4 rounded-2xl transition-all active-press shadow-md ${isCurrentAyah ? 'bg-black text-white' : 'bg-white text-gray-300 hover:text-black dark:bg-gray-800 border border-gray-100'}`}>
                                    {isCurrentAyah && isPlaying ? <Pause size={26} /> : <Play size={26} />}
                                </button>
                            </div>
                        </div>

                        <div className="text-right mb-16 px-4" dir="rtl" style={{ overflow: 'visible' }}>
                            <p className={`font-indopak ${getFontClasses()}`} style={{ width: '100%', wordBreak: 'keep-all' }}>
                                {ayah.text} <span className="text-black/10 mx-6 select-none inline-block align-middle transform translate-y-2">۝</span>
                            </p>
                        </div>

                        {settings.showTafseer && tafseerAyah && (
                            <div className="text-right border-r-[12px] border-black/10 pr-12 mb-6" dir="rtl" style={{ overflow: 'visible' }}>
                                <p 
                                    className={`font-urdu transition-colors duration-300 ${
                                        settings.theme === 'dark' ? 'text-emerald-50' : 'text-gray-900'
                                    }`}
                                    style={getTafseerStyle()}
                                >
                                    {tafseerAyah.text}
                                </p>
                            </div>
                        )}
                    </div>
                );
            })}

            {data && visibleCount < data.arabicAyahs.length && (
              <div ref={loadMoreRef} className="h-96 flex flex-col items-center justify-center gap-6">
                 <Loader2 className="animate-spin text-black" size={64} />
                 <p className="text-xs font-black text-black/30 uppercase tracking-[0.5em]">Continuing the Revelation</p>
              </div>
            )}
        </div>
      </main>

      {isPlaying && (
          <div className="fixed bottom-10 left-1/2 transform -translate-x-1/2 z-[70] bg-black text-white px-10 py-6 rounded-[3rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.6)] flex items-center gap-10 border border-white/20 backdrop-blur-3xl transition-all scale-110">
             <button onClick={() => { if(currentAyahIndex > 0) setCurrentAyahIndex(prev => prev - 1); }} disabled={currentAyahIndex <= 0} className="p-3 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipBack size={28} /></button>
             <button onClick={() => setIsPlaying(!isPlaying)} className="w-16 h-16 flex items-center justify-center bg-gold-500 text-black rounded-full shadow-2xl active-press group hover:scale-105 transition-transform">
                {isPlaying ? <Pause size={32} className="fill-current" /> : <Play size={32} className="fill-current" />}
             </button>
             <button onClick={() => { if(currentAyahIndex < (data?.arabicAyahs.length || 0) - 1) setCurrentAyahIndex(prev => prev + 1); }} disabled={currentAyahIndex >= (data?.arabicAyahs.length || 0) - 1} className="p-3 opacity-60 hover:opacity-100 active-press disabled:opacity-20"><SkipForward size={28} /></button>
             <div className="h-12 w-px bg-white/20 mx-2"></div>
             <button onClick={() => { setIsPlaying(false); setCurrentAyahIndex(-1); }} className="p-3 opacity-60 hover:text-red-400 hover:opacity-100 active-press"><X size={28} /></button>
          </div>
      )}

      <AIChat 
        isOpen={showChat} 
        onClose={() => setShowChat(false)} 
        context={`Reading Surah ${data?.surahInfo.englishName} in the authentic Taj Quran Lahore style. Currently at Ayah ${currentAyahIndex + 1}.`} 
      />
    </div>
  );
};

export default Reader;

